// ==WindhawkMod==
// @id              context-menu-preloader
// @name            Context Menu Preloader
// @description     Preloads and pins your context menu handlers into RAM to improve performance.
// @version         1.0
// @author          Lockframe
// @github          https://github.com/Lockframe
// @include         explorer.exe
// @compilerOptions -lgdi32 -lole32 -luuid -lshlwapi -lpsapi
// ==/WindhawkMod==

// ==WindhawkModReadme==
/*
# Context Menu Preloader

Preloads your desired context menu handlers (txt; mp4; svg) and pins them to your RAM for nigh-instant loading of context menus.

Certain handlers are blocked by default because they interfere with Bluetooth.

Does not affect context menus inside applications nor File Explorer's WinUI 3 context menu.

*/
// ==/WindhawkModReadme==

// ==WindhawkModSettings==
/*
- StartupDelay: 5
  $name: Startup Delay (Seconds)
  $description: Wait time before locking handlers.
- CustomExtensions: "pdf; mp4; mkv; docx; obj; html"
  $name: Custom Extensions
  $description: Extensions to preload and pin. Separate with each ';'.
- EnableDebug: false
  $name: Enable Debug Logging and RAM usage report.
*/
// ==/WindhawkModSettings==

#include <windhawk_utils.h>
#include <shlwapi.h>
#include <psapi.h>
#include <vector>
#include <string>
#include <sstream>
#include <atomic>
#include <unordered_set>
#include <algorithm>
#include <mutex>

// -------------------------------------------------------------------------
// Globals
// -------------------------------------------------------------------------
static std::atomic<int> g_delay{5};
static std::atomic<bool> g_debug{false};
static std::atomic<bool> g_quitting{false}; 
static HANDLE g_hThread = NULL;             
static HANDLE g_hQuitEvent = NULL;      

static std::vector<std::wstring> g_customExts;
static std::unordered_set<std::wstring> g_pinnedDlls;
static std::mutex g_pinMutex;

// -------------------------------------------------------------------------
// Logging
// -------------------------------------------------------------------------
void Log(LPCWSTR fmt, ...) {
    if (!g_debug.load(std::memory_order_relaxed)) return;
    va_list args;
    va_start(args, fmt);
    WCHAR buf[1024];
    vswprintf_s(buf, fmt, args);
    va_end(args);
    Wh_Log(L"[Accelerator] %s", buf);
}

// -------------------------------------------------------------------------
// Utils
// -------------------------------------------------------------------------
void ParseExtensions(const std::wstring& input) {
    g_customExts.clear();
    std::wstringstream ss(input);
    std::wstring item;
    while (std::getline(ss, item, L';')) {
        size_t first = item.find_first_not_of(L" ");
        if (first == std::string::npos) continue;
        size_t last = item.find_last_not_of(L" ");
        std::wstring cleanExt = item.substr(first, (last - first + 1));
        if (!cleanExt.empty() && cleanExt[0] == L'.') cleanExt = cleanExt.substr(1);
        if (!cleanExt.empty()) g_customExts.push_back(cleanExt);
    }
}

std::wstring ToLower(const std::wstring& input) {
    std::wstring out = input;
    std::transform(out.begin(), out.end(), out.begin(), towlower);
    return out;
}

// -------------------------------------------------------------------------
// RAM Monitoring
// -------------------------------------------------------------------------
SIZE_T GetRamUsage() {
    PROCESS_MEMORY_COUNTERS pmc;
    if (GetProcessMemoryInfo(GetCurrentProcess(), &pmc, sizeof(pmc))) {
        return pmc.WorkingSetSize;
    }
    return 0;
}

// -------------------------------------------------------------------------
// Blocklist & Pinner
// -------------------------------------------------------------------------
bool IsBlacklisted(const std::wstring& name, const std::wstring& dllPath) {
    std::wstring nameLower = ToLower(name);
    std::wstring pathLower = ToLower(dllPath);

    // 1. Nearby Sharing / Bluetooth / Network
    if (pathLower.find(L"ntshrui.dll") != std::wstring::npos) return true; 
    if (pathLower.find(L"filesyncshell64.dll") != std::wstring::npos) return true;
    if (pathLower.find(L"workfolders") != std::wstring::npos) return true;
    if (pathLower.find(L"sharing") != std::wstring::npos) return true;
    
    // 2. Managed / .NET
    if (pathLower.find(L"mscoree.dll") != std::wstring::npos) return true;

    // 3. System UI / Brokers
    if (pathLower.find(L"appresolver.dll") != std::wstring::npos) return true; 
    if (pathLower.find(L"acppage.dll") != std::wstring::npos) return true;
    if (pathLower.find(L"twinui") != std::wstring::npos) return true;
    if (pathLower.find(L"windows.share") != std::wstring::npos) return true;
    if (pathLower.find(L"datatransfer") != std::wstring::npos) return true;

    // 4. Casting / Bluetooth Legacy
    if (pathLower.find(L"playtomenu.dll") != std::wstring::npos) return true;
    if (nameLower.find(L"play to") != std::wstring::npos) return true;
    if (pathLower.find(L"bluetooth") != std::wstring::npos) return true;
    if (pathLower.find(L"fsquirt.dll") != std::wstring::npos) return true;

    // 5. Native
    if (pathLower.find(L"windows defender") != std::wstring::npos) return true;
    if (pathLower.find(L"shellext.dll") != std::wstring::npos) return true;
    if (pathLower.find(L"zipfldr.dll") != std::wstring::npos) return true;
    
    // 6. Printers
    if (nameLower.find(L"print") != std::wstring::npos) return true;

    return false;
}

void PinDLL(const std::wstring& dllPath, const std::wstring& debugName) {
    if (g_quitting.load()) return; 
    if (dllPath.empty()) return;
    
    std::wstring pathLower = ToLower(dllPath);

    // 1. Lock only to read the set
    {
        std::lock_guard<std::mutex> lock(g_pinMutex);
        if (g_pinnedDlls.count(pathLower)) return; 
    }

    if (IsBlacklisted(debugName, pathLower)) {
        Log(L"BLOCKED: %s", debugName.c_str());
        return;
    }

    if (pathLower.find(L"\\") != std::wstring::npos && GetFileAttributesW(dllPath.c_str()) == INVALID_FILE_ATTRIBUTES) {
        Log(L"Skipped (Not Found): %s", dllPath.c_str());
        return;
    }

    // Call LoadLibrary OUTSIDE the lock to prevent OS Loader deadlocks
    HMODULE hMod = LoadLibraryW(dllPath.c_str());
    if (hMod) {
        HMODULE hPinned = NULL;
        if (GetModuleHandleExW(GET_MODULE_HANDLE_EX_FLAG_PIN | GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS, 
                              (LPCWSTR)hMod, &hPinned)) {
            // 2. Lock only to write to the set
            std::lock_guard<std::mutex> lock(g_pinMutex);
            g_pinnedDlls.insert(pathLower); 
            Log(L"Pinned: %s", dllPath.c_str());
        } else {
            FreeLibrary(hMod);
            Log(L"Failed to pin (Freed safely): %s", dllPath.c_str());
        }
    } else {
        Log(L"Failed to load: %s", dllPath.c_str());
    }
}

// -------------------------------------------------------------------------
// Registry Walker Logic
// -------------------------------------------------------------------------
HKEY OpenKey(HKEY hRoot, LPCWSTR path) {
    HKEY hKey = NULL;
    if (RegOpenKeyExW(hRoot, path, 0, KEY_READ, &hKey) == ERROR_SUCCESS) return hKey;
    return NULL;
}

std::wstring ReadDefaultValue(HKEY hKey, LPCWSTR subKey = NULL) {
    WCHAR buf[1024];
    DWORD size = sizeof(buf);
    HKEY hTarget = hKey;
    
    if (subKey) {
        hTarget = OpenKey(hKey, subKey);
        if (!hTarget) return L"";
    }

    LONG res = RegQueryValueExW(hTarget, NULL, NULL, NULL, (LPBYTE)buf, &size);
    if (subKey) RegCloseKey(hTarget);
    
    if (res == ERROR_SUCCESS && size > 0) {
        DWORD maxChars = sizeof(buf) / sizeof(WCHAR);
        DWORD charsRead = size / sizeof(WCHAR);
        
        if (charsRead < maxChars) {
            buf[charsRead] = L'\0';
        } else {
            buf[maxChars - 1] = L'\0';
        }
        return std::wstring(buf);
    }
    return L"";
}

std::wstring ReadNamedValue(HKEY hKey, LPCWSTR valueName) {
    WCHAR buf[1024];
    DWORD size = sizeof(buf);
    
    if (RegQueryValueExW(hKey, valueName, NULL, NULL, (LPBYTE)buf, &size) == ERROR_SUCCESS && size > 0) {
        DWORD maxChars = sizeof(buf) / sizeof(WCHAR);
        DWORD charsRead = size / sizeof(WCHAR);
        
        if (charsRead < maxChars) buf[charsRead] = L'\0';
        else buf[maxChars - 1] = L'\0';
        
        return std::wstring(buf);
    }
    return L"";
}

void ProcessCLSID(const std::wstring& clsidStr, const std::wstring& parentName) {
    if (g_quitting.load()) return;
    if (clsidStr.empty()) return;
    if (clsidStr == L"{6af09ec9-b429-11d4-a1fb-0090273514e2}") return;
    if (clsidStr == L"{e2bf9676-5f8f-435c-97eb-11607a5bedf7}") return;

    std::wstring keyPath = L"CLSID\\" + clsidStr + L"\\InProcServer32";
    HKEY hKey = OpenKey(HKEY_CLASSES_ROOT, keyPath.c_str());
    if (hKey) {
        std::wstring dllPath = ReadDefaultValue(hKey);
        RegCloseKey(hKey);
        
        if (dllPath.empty()) return;

        // Strip quotes if they exist before expanding environment strings
        if (dllPath.front() == L'"') {
            size_t endQuote = dllPath.find(L'"', 1);
            if (endQuote != std::wstring::npos) {
                dllPath = dllPath.substr(1, endQuote - 1);
            }
        }

        // Strip the '@' prefix used by MUI string definitions
        if (!dllPath.empty() && dllPath.front() == L'@') {
            dllPath = dllPath.substr(1);
        }

        // Strip resource indices (e.g., ", -100" or ", 1")
        size_t commaPos = dllPath.find(L',');
        if (commaPos != std::wstring::npos) {
            dllPath = dllPath.substr(0, commaPos);
        }
        
        // Support extended length Windows paths since MAX_PATH is hardcoded to 260 characters
        WCHAR expanded[32768];
        ExpandEnvironmentStringsW(dllPath.c_str(), expanded, 32768);
        
        PinDLL(expanded, parentName.empty() ? clsidStr : parentName);
    }
}

void ScanKeyForHandlers(HKEY hRoot, const std::wstring& path) {
    if (g_quitting.load()) return;
    HKEY hKey = OpenKey(hRoot, path.c_str());
    if (!hKey) return;

    WCHAR subKeyName[256];
    DWORD index = 0;
    DWORD len = 256;

    while (RegEnumKeyExW(hKey, index, subKeyName, &len, NULL, NULL, NULL, NULL) == ERROR_SUCCESS) {
        if (g_quitting.load()) break; // Exit loop fast
        
        std::wstring name = subKeyName;
        if (subKeyName[0] == L'{') {
            ProcessCLSID(subKeyName, L"");
        } else {
            HKEY hSub = OpenKey(hKey, subKeyName);
            if (hSub) {
                std::wstring val = ReadDefaultValue(hSub);
                if (!val.empty() && val[0] == L'{') ProcessCLSID(val, name);
                RegCloseKey(hSub);
            }
        }
        len = 256;
        index++;
    }
    RegCloseKey(hKey);
}

void ScanShellVerbs(HKEY hRoot, const std::wstring& path) {
    if (g_quitting.load()) return;
    HKEY hKey = OpenKey(hRoot, path.c_str());
    if (!hKey) return;

    WCHAR verbName[256];
    DWORD index = 0;
    DWORD len = 256;

    while (RegEnumKeyExW(hKey, index, verbName, &len, NULL, NULL, NULL, NULL) == ERROR_SUCCESS) {
        if (g_quitting.load()) break;
        
        HKEY hVerb = OpenKey(hKey, verbName);
        if (hVerb) {
            std::wstring cmdHandler = ReadNamedValue(hVerb, L"ExplorerCommandHandler");
            if (!cmdHandler.empty()) ProcessCLSID(cmdHandler, L"ExplorerCommandHandler");

            HKEY hDrop = OpenKey(hVerb, L"DropTarget");
            if (hDrop) {
                std::wstring clsid = ReadNamedValue(hDrop, L"CLSID");
                if (!clsid.empty()) ProcessCLSID(clsid, L"DropTarget");
                RegCloseKey(hDrop);
            }

            HKEY hCmd = OpenKey(hVerb, L"command");
            if (hCmd) {
                std::wstring delegateId = ReadNamedValue(hCmd, L"DelegateExecute");
                if (!delegateId.empty()) ProcessCLSID(delegateId, L"DelegateExecute");
                RegCloseKey(hCmd);
            }
            RegCloseKey(hVerb);
        }
        len = 256;
        index++;
    }
    RegCloseKey(hKey);
}

void OptimizeExtension(const std::wstring& ext) {
    if (g_quitting.load()) return;
    Log(L"Scanning .%s", ext.c_str());
    
    // Scan Legacy Handlers
    ScanKeyForHandlers(HKEY_CLASSES_ROOT, L"." + ext + L"\\ShellEx\\ContextMenuHandlers");
    ScanKeyForHandlers(HKEY_CLASSES_ROOT, L"SystemFileAssociations\\." + ext + L"\\ShellEx\\ContextMenuHandlers");

    // Scan Modern Handlers
    ScanShellVerbs(HKEY_CLASSES_ROOT, L"." + ext + L"\\shell");
    ScanShellVerbs(HKEY_CLASSES_ROOT, L"SystemFileAssociations\\." + ext + L"\\shell");

    HKEY hExtKey = OpenKey(HKEY_CLASSES_ROOT, (L"." + ext).c_str());
    if (hExtKey) {
        // Read explicit ProgID
        std::wstring progID = ReadDefaultValue(hExtKey);
        if (!progID.empty()) {
            ScanKeyForHandlers(HKEY_CLASSES_ROOT, progID + L"\\ShellEx\\ContextMenuHandlers");
            ScanShellVerbs(HKEY_CLASSES_ROOT, progID + L"\\shell");
        }

        // Read PerceivedType (Crucial for Audio, Video, and Document files)
        WCHAR perceived[64];
        DWORD size = sizeof(perceived);
        if (RegQueryValueExW(hExtKey, L"PerceivedType", NULL, NULL, (LPBYTE)perceived, &size) == ERROR_SUCCESS) {
            std::wstring pType(perceived);
            ScanKeyForHandlers(HKEY_CLASSES_ROOT, L"SystemFileAssociations\\" + pType + L"\\ShellEx\\ContextMenuHandlers");
            ScanShellVerbs(HKEY_CLASSES_ROOT, L"SystemFileAssociations\\" + pType + L"\\shell");
        }
        
        RegCloseKey(hExtKey);
    }
}

// -------------------------------------------------------------------------
// Main Thread
// -------------------------------------------------------------------------
DWORD WINAPI WalkerThread(LPVOID) {
    int delay = g_delay.load();
    if (delay < 1) delay = 1;

    // 0% CPU Idle Wait
    // Sleeps for 'delay' seconds. If g_hQuitEvent is signaled during this time, it wakes up and returns WAIT_OBJECT_0
    if (WaitForSingleObject(g_hQuitEvent, delay * 1000) == WAIT_OBJECT_0) {
        return 0; // The event was triggered (mod is shutting down or reloading), so exit early
    }

    Log(L"Startup (v1.0)");
    
    // Initialize COM for this thread so Shell Extensions don't crash on load
    HRESULT hrCom = CoInitializeEx(NULL, COINIT_APARTMENTTHREADED);

    // Capture Baseline RAM
    SIZE_T startMem = GetRamUsage();

    // 1. Priority: Nilesoft
    HMODULE hShell = LoadLibraryW(L"shell.dll");
    if (hShell) {
        WCHAR path[MAX_PATH];
        GetModuleFileNameW(hShell, path, MAX_PATH);
        PinDLL(path, L"Nilesoft Shell");
    }

    // 2. Priority: Image Handlers (Force Pin)
    WCHAR sysDir[MAX_PATH];
    GetSystemDirectoryW(sysDir, MAX_PATH);
    std::wstring sysPath = sysDir;
    PinDLL(L"C:\\Program Files\\Windows Photo Viewer\\PhotoViewer.dll", L"PhotoViewer (Force)");
    PinDLL(sysPath + L"\\shimgvw.dll", L"Legacy Image Viewer");

    // 3. Global Handlers & Verbs
    ScanKeyForHandlers(HKEY_CLASSES_ROOT, L"*\\ShellEx\\ContextMenuHandlers");
    ScanShellVerbs(HKEY_CLASSES_ROOT, L"*\\shell");
    
    ScanKeyForHandlers(HKEY_CLASSES_ROOT, L"AllFileSystemObjects\\ShellEx\\ContextMenuHandlers");
    ScanShellVerbs(HKEY_CLASSES_ROOT, L"AllFileSystemObjects\\shell");
    
    ScanKeyForHandlers(HKEY_CLASSES_ROOT, L"Directory\\Background\\ShellEx\\ContextMenuHandlers");
    ScanShellVerbs(HKEY_CLASSES_ROOT, L"Directory\\Background\\shell");
    
    ScanKeyForHandlers(HKEY_CLASSES_ROOT, L"Directory\\ShellEx\\ContextMenuHandlers");
    ScanShellVerbs(HKEY_CLASSES_ROOT, L"Directory\\shell");
    
    ScanKeyForHandlers(HKEY_CLASSES_ROOT, L"Folder\\ShellEx\\ContextMenuHandlers");
    ScanShellVerbs(HKEY_CLASSES_ROOT, L"Folder\\shell");

    // 4. System File Associations for Images
    ScanKeyForHandlers(HKEY_CLASSES_ROOT, L"SystemFileAssociations\\image\\ShellEx\\ContextMenuHandlers");

    // 5. Custom Extensions
    for (const auto& ext : g_customExts) {
        OptimizeExtension(ext);
    }

    // Capture Final RAM
    SIZE_T endMem = GetRamUsage();
    
    // Calculate Delta (safely)
    double deltaMB = 0.0;
    if (endMem > startMem) {
        deltaMB = (double)(endMem - startMem) / (1024.0 * 1024.0);
    }

    Log(L"Done. Total RAM Impact: %.2f MB", deltaMB);
    
    // Cleanup COM
    if (SUCCEEDED(hrCom)) {
        CoUninitialize();
    }
    
    return 0;
}

// -------------------------------------------------------------------------
// Init
// -------------------------------------------------------------------------
void LoadSettings() {
    g_delay.store(Wh_GetIntSetting(L"StartupDelay"));
    g_debug.store(Wh_GetIntSetting(L"EnableDebug"));
    
    PCWSTR customExtsRaw = Wh_GetStringSetting(L"CustomExtensions");
    if (customExtsRaw) {
        ParseExtensions(customExtsRaw);
        Wh_FreeStringSetting(customExtsRaw);
    }
}

BOOL Wh_ModInit() {
    LoadSettings();
    g_quitting.store(false);
    
    // Manual-reset event, initially unsignaled
    g_hQuitEvent = CreateEventW(NULL, TRUE, FALSE, NULL);
    
    g_hThread = CreateThread(NULL, 0, WalkerThread, NULL, 0, NULL);
    return TRUE;
}

void Wh_ModSettingsChanged() {
    Log(L"Settings changed. Restarting preloader thread...");
    LoadSettings();

    // Safely kill the existing thread
    g_quitting.store(true);
    if (g_hQuitEvent) SetEvent(g_hQuitEvent); // Wake up the sleeping thread

    if (g_hThread) {
        WaitForSingleObject(g_hThread, INFINITE);
        CloseHandle(g_hThread);
        g_hThread = NULL;
    }

    // Spin up a new thread for the new settings
    g_quitting.store(false);
    if (g_hQuitEvent) ResetEvent(g_hQuitEvent); // Reset the event back to unsignaled
    
    g_hThread = CreateThread(NULL, 0, WalkerThread, NULL, 0, NULL);
}

void Wh_ModUninit() {
    g_quitting.store(true);
    if (g_hQuitEvent) SetEvent(g_hQuitEvent); // Wake up the sleeping thread
    
    if (g_hThread) {
        WaitForSingleObject(g_hThread, INFINITE);
        CloseHandle(g_hThread);
        g_hThread = NULL;
    }
    
    // Safely destroy the Event handle to prevent memory leaks
    if (g_hQuitEvent) {
        CloseHandle(g_hQuitEvent);
        g_hQuitEvent = NULL;
    }
}

// ==WindhawkMod==
// @id              control-panel-color-fix
// @name            Control Panel Color Fix
// @description     For custom themes, fixes white header and sidebar in Control Panel
// @version         1.0.1
// @author          chip33
// @github          https://github.com/chip33
// @include         explorer.exe
// @include         systemsettings.exe
// @compilerOptions -luxtheme -lgdi32
// ==/WindhawkMod==

// ==WindhawkModSettings==
/*
- contrastEnabled: true
  $name: Header/Sidebar contrast offset

- contrastOffset: 22
  $name: " "
  $description: If Control Panel body color is 32,32,32, an offset of +22 lightens the header/sidebar to 54,54,54. Negative values darken.

- useManualRGB: false
  $name: Header/Sidebar color override

- manualRGB: "54,54,54"
  $name: " "
  $description: "Custom RGB color. Range: 0,0,0 (black) to 255,255,255 (white)."
*/
// ==/WindhawkModSettings==

// ==WindhawkModReadme==
/*
# Control Panel Color Fix

Repaint the hardcoded white header and sidebar to match the custom theme.

Optional ± contrast offset between Control Panel body and header/sidebar.

Manual header/sidebar color override.

### **Dark theme**

| Original | Contrast offset |
|----------|-----------------|
| ![Control Panel before](https://raw.githubusercontent.com/chip33/images/main/wh/cpcf/cpcf-cp-b.png) | ![Control Panel after](https://raw.githubusercontent.com/chip33/images/main/wh/cpcf/cpcf-cp-a.png) |
| ![Recovery before](https://raw.githubusercontent.com/chip33/images/main/wh/cpcf/cpcf-recovery-b.png) | ![Recovery after](https://raw.githubusercontent.com/chip33/images/main/wh/cpcf/cpcf-recovery-a.png) |

### **Dark theme with mica**

Original | Contrast offset |
|----------|-----------------|
| ![Control Panel mica before](https://raw.githubusercontent.com/chip33/images/main/wh/cpcf/cpcf-cp-mica-b.png) | ![Control Panel mica after](https://raw.githubusercontent.com/chip33/images/main/wh/cpcf/cpcf-cp-mica-a.png) |
| ![Recovery mica before](https://raw.githubusercontent.com/chip33/images/main/wh/cpcf/cpcf-recovery-mica-b.png) | ![Recovery mica after](https://raw.githubusercontent.com/chip33/images/main/wh/cpcf/cpcf-recovery-mica-a.png) |
*/
// ==/WindhawkModReadme==

// Based on earlier uxtheme-hook versions by rounk-ctrl.

#include <windows.h>
#include <uxtheme.h>
#include <vssym32.h>   // TMT_FILLCOLOR, TMT_TEXTCOLOR
#include <windhawk_api.h>
#include <windhawk_utils.h>
#include <algorithm>
#include <string>

#ifdef _WIN64
#define STDCALL __cdecl
#define SSTDCALL L"__cdecl"
#else
#define STDCALL __stdcall
#define SSTDCALL L"__stdcall"
#endif

typedef VOID(STDCALL *Element_PaintBgT)(
    class Element*, HDC, class Value*, LPRECT, LPRECT, LPRECT, LPRECT);
static Element_PaintBgT Element_PaintBg = nullptr;

// ---------------------------
// Settings state
// ---------------------------
static bool g_contrastEnabled = true;
static int  g_contrastOffset  = 22;
static bool g_useManualRGB    = false;
static COLORREF g_manualRGB   = RGB(54,54,54);

// ---------------------------
// Helpers
// ---------------------------

// Parse "R,G,B" user setting to COLORREF.
// Example input: "34,35,40" → RGB(34,35,40).
static COLORREF ParseRGBString(const std::wstring& rgbStr) {
    int r = 0, g = 0, b = 0;
    if (swscanf(rgbStr.c_str(), L"%d,%d,%d", &r, &g, &b) == 3) {
        if (r >= 0 && r <= 255 &&
            g >= 0 && g <= 255 &&
            b >= 0 && b <= 255) {
            return RGB(r, g, b);
        }
    }
    // Fallback to default on invalid input.
    return g_manualRGB;
}

// Apply a uniform contrast delta to all channels while preserving hue.
// Positive values lighten, negative values darken.
// Example: RGB(30,60,200) +22 → RGB(52,82,222).
static COLORREF ApplyDelta(COLORREF base, int delta) {
    int r = std::clamp(GetRValue(base) + delta, 0, 255);
    int g = std::clamp(GetGValue(base) + delta, 0, 255);
    int b = std::clamp(GetBValue(base) + delta, 0, 255);
    return RGB(r, g, b);
}

// Fill a rectangle with a solid color.
static void FillRectColor(HDC hdc, const RECT* rc, COLORREF color) {
    if (!rc) return;
    // Skip if rect is empty or inverted (no drawable area).
    if (rc->right <= rc->left || rc->bottom <= rc->top) return;
    HBRUSH brush = CreateSolidBrush(color);
    FillRect(hdc, rc, brush);
    DeleteObject(brush);
}

// Detect if theme alters Control Panel body color (TMT_FILLCOLOR).
static bool ThemeAltersCPBody(HWND wnd) {
    constexpr COLORREF kDefaultCPBody = RGB(255,255,255); // Default CP body = white.
    HTHEME hTh = OpenThemeData(wnd, L"ControlPanel");
    if (!hTh) {
        Wh_Log(L"Failed to open theme data, skipping repaint.");
        return false;
    }

    // Fallback default if theme query fails.
    COLORREF clrBody = kDefaultCPBody;
    // partId=2, stateId=0 = Control Panel body color.
    // Not officially documented, identified through testing.
    if (SUCCEEDED(GetThemeColor(hTh, 2, 0, TMT_FILLCOLOR, &clrBody))) {
        // StartAllBack repaints visually but leaves TMT_FILLCOLOR at default,
        // so any significant difference means the theme has altered Control Panel.
        const int tolerance = 2; // Ignore small rounding drift from theme API.
        if (abs(GetRValue(clrBody) - GetRValue(kDefaultCPBody)) > tolerance ||
            abs(GetGValue(clrBody) - GetGValue(kDefaultCPBody)) > tolerance ||
            abs(GetBValue(clrBody) - GetBValue(kDefaultCPBody)) > tolerance) {
            CloseThemeData(hTh);
            return true;
        }
    } else Wh_Log(L"Failed to get theme color, skipping repaint.");

    CloseThemeData(hTh);
    return false;
}

// ---------------------------
// Settings load
// ---------------------------
static void LoadSettings() {
    g_contrastEnabled = Wh_GetIntSetting(L"contrastEnabled") != 0;
    g_contrastOffset  = Wh_GetIntSetting(L"contrastOffset");
    g_useManualRGB    = Wh_GetIntSetting(L"useManualRGB") != 0;
    g_manualRGB       = ParseRGBString(Wh_GetStringSetting(L"manualRGB"));
}

// ---------------------------
// Hook
// ---------------------------
VOID STDCALL Element_PaintBgHook(
    class Element* This, HDC hdc, class Value* value,
    LPRECT pRect, LPRECT pClipRect, LPRECT pExcludeRect, LPRECT pTargetRect)
{
    // No theme value; call original function.
    if (!value) {
        Element_PaintBg(This, hdc, value, pRect, pClipRect, pExcludeRect, pTargetRect);
        return;
    }

    int elementType = (int)(*(DWORD*)value << 26) >> 26;
    if (elementType != 9 && pRect) {
        auto rawValueField   = *((unsigned __int64*)value + 1);
        auto elementTypeCode = (rawValueField + 20) & 7;

        // Observed mapping; not officially documented, identified through testing.
        // 6 -> selection
        // 3 -> hovered
        // 4 -> Control Panel header and sidebar
        // 1 -> cp_hub_frame (new Control Panel page style)

        static const bool debug = false; // set true when testing
        if (debug) Wh_Log(L"elementTypeCode=%llu elementType=%d", elementTypeCode, elementType);

        if (elementTypeCode == 4) {
            HWND wnd = WindowFromDC(hdc);
            // Repaint only if theme alters CP body color; avoids StartAllBack conflicts and redundant draws.
            if (ThemeAltersCPBody(wnd)) {
                HTHEME hTh = OpenThemeData(wnd, L"ControlPanel");
                // Fallback default if theme query fails (dark body baseline).
                COLORREF clrBody = RGB(32,32,32);
                if (hTh) {
                    // Query CP body color (TMT_FILLCOLOR, partId=2, stateId=0).
                    // Not officially documented, identified through testing.
                    GetThemeColor(hTh, 2, 0, TMT_FILLCOLOR, &clrBody);
                    CloseThemeData(hTh);
                }

                COLORREF clrHeader;
                if (g_useManualRGB) {
                    // Manual override: use configured RGB value.
                    clrHeader = g_manualRGB;
                } else if (g_contrastEnabled) {
                    // Contrast enabled: apply delta to body color.
                    clrHeader = ApplyDelta(clrBody, g_contrastOffset);
                } else {
                    // Contrast disabled: use body color unchanged.
                    clrHeader = clrBody;
                }

                FillRectColor(hdc, pRect, clrHeader);

                // Short-circuit: skip original repaint (prevents StartAllBack overwrite).
                return;
            } else {
                // Theme does not alter CP body; call original function.
                Element_PaintBg(This, hdc, value, pRect, pClipRect, pExcludeRect, pTargetRect);
                return;
            }
        }
    }

    // Non-header/sidebar elements; call original function.
    Element_PaintBg(This, hdc, value, pRect, pClipRect, pExcludeRect, pTargetRect);
}

