// AMD Display Library (ADL) is loaded dynamically. No SDK/lib is required.
// Temperature strategy:
//   1) ADL2_OverdriveN_Temperature_Get (newer Radeon / Ryzen iGPU drivers)
//   2) ADL_Overdrive5_Temperature_Get (legacy fallback)
// This avoids showing "--°C" merely because Overdrive5 isn't exposed.
constexpr int ADL_MAX_PATH = 256;
constexpr int ADL_OK = 0;

struct ADLAdapterInfo {
    int iSize;
    int iAdapterIndex;
    char strUDID[ADL_MAX_PATH];
    int iBusNumber;
    int iDeviceNumber;
    int iFunctionNumber;
    int iVendorID;
    char strAdapterName[ADL_MAX_PATH];
    char strDisplayName[ADL_MAX_PATH];
    int iPresent;
    int iExist;
    char strDriverPath[ADL_MAX_PATH];
    char strDriverPathExt[ADL_MAX_PATH];
    char strPNPString[ADL_MAX_PATH];
    int iOSDisplayIndex;
};

struct ADLTemperature {
    int iSize;
