};

using ADL_MAIN_MALLOC_CALLBACK = void* (__stdcall*)(int);
using ADL_CONTEXT_HANDLE = void*;

using ADL2_Main_Control_Create_t =
    int(__stdcall*)(ADL_MAIN_MALLOC_CALLBACK, int, ADL_CONTEXT_HANDLE*);
using ADL2_Main_Control_Destroy_t = int(__stdcall*)(ADL_CONTEXT_HANDLE);
using ADL2_Adapter_NumberOfAdapters_Get_t =
    int(__stdcall*)(ADL_CONTEXT_HANDLE, int*);
using ADL2_Adapter_AdapterInfo_Get_t =
    int(__stdcall*)(ADL_CONTEXT_HANDLE, ADLAdapterInfo*, int);
using ADL2_OverdriveN_Temperature_Get_t =
    int(__stdcall*)(ADL_CONTEXT_HANDLE, int, int, int*);

using ADL_Main_Control_Create_t = int(__stdcall*)(ADL_MAIN_MALLOC_CALLBACK, int);
using ADL_Main_Control_Destroy_t = int(__stdcall*)();
using ADL_Adapter_NumberOfAdapters_Get_t = int(__stdcall*)(int*);
using ADL_Adapter_AdapterInfo_Get_t = int(__stdcall*)(ADLAdapterInfo*, int);
using ADL_Overdrive5_Temperature_Get_t =
    int(__stdcall*)(int, int, ADLTemperature*);

HMODULE g_adlModule = nullptr;
ADL_CONTEXT_HANDLE g_adlContext = nullptr;

ADL2_Main_Control_Destroy_t g_adl2Destroy = nullptr;
ADL2_Adapter_NumberOfAdapters_Get_t g_adl2AdapterCount = nullptr;
ADL2_Adapter_AdapterInfo_Get_t g_adl2AdapterInfo = nullptr;
ADL2_OverdriveN_Temperature_Get_t g_adl2TemperatureGet = nullptr;

ADL_Main_Control_Destroy_t g_adlDestroy = nullptr;
ADL_Adapter_NumberOfAdapters_Get_t g_adlAdapterCount = nullptr;
ADL_Adapter_AdapterInfo_Get_t g_adlAdapterInfo = nullptr;
ADL_Overdrive5_Temperature_Get_t g_adlTemperatureGet = nullptr;

std::vector<int> g_adlAdapterIndices;
bool g_adlUsingAdl2 = false;
bool g_adlInitAttempted = false;

void* __stdcall AdlAlloc(int size) {
    if (size <= 0)
        return nullptr;
    return HeapAlloc(GetProcessHeap(), HEAP_ZERO_MEMORY,
                     static_cast<SIZE_T>(size));
}

void ResetAdlFunctionPointers() {
    g_adlContext = nullptr;
    g_adl2Destroy = nullptr;
    g_adl2AdapterCount = nullptr;
    g_adl2AdapterInfo = nullptr;
    g_adl2TemperatureGet = nullptr;
    g_adlDestroy = nullptr;
    g_adlAdapterCount = nullptr;
    g_adlAdapterInfo = nullptr;
    g_adlTemperatureGet = nullptr;
    g_adlAdapterIndices.clear();
    g_adlUsingAdl2 = false;
}

bool InitGpuTemperature() {
    if (g_adlModule)
        return !g_adlAdapterIndices.empty() &&
               (g_adl2TemperatureGet || g_adlTemperatureGet);

    // Don't repeatedly LoadLibrary/GetProcAddress every refresh if unsupported.
    if (g_adlInitAttempted)
        return false;
    g_adlInitAttempted = true;

    g_adlModule = LoadLibraryW(L"atiadlxx.dll");
    if (!g_adlModule)
        g_adlModule = LoadLibraryW(L"atiadlxy.dll");
    if (!g_adlModule)
        return false;

    // Prefer ADL2 + OverdriveN. This is the important path for modern Radeon
    // drivers and Ryzen integrated graphics.
    auto adl2Create = reinterpret_cast<ADL2_Main_Control_Create_t>(
        GetProcAddress(g_adlModule, "ADL2_Main_Control_Create"));
    g_adl2Destroy = reinterpret_cast<ADL2_Main_Control_Destroy_t>(
        GetProcAddress(g_adlModule, "ADL2_Main_Control_Destroy"));
    g_adl2AdapterCount =
        reinterpret_cast<ADL2_Adapter_NumberOfAdapters_Get_t>(
            GetProcAddress(g_adlModule, "ADL2_Adapter_NumberOfAdapters_Get"));
    g_adl2AdapterInfo = reinterpret_cast<ADL2_Adapter_AdapterInfo_Get_t>(
        GetProcAddress(g_adlModule, "ADL2_Adapter_AdapterInfo_Get"));
    g_adl2TemperatureGet =
        reinterpret_cast<ADL2_OverdriveN_Temperature_Get_t>(
            GetProcAddress(g_adlModule, "ADL2_OverdriveN_Temperature_Get"));

    int adapterCount = 0;
    if (adl2Create && g_adl2Destroy && g_adl2AdapterCount &&
        g_adl2AdapterInfo && g_adl2TemperatureGet &&
        adl2Create(AdlAlloc, 1, &g_adlContext) == ADL_OK &&
        g_adlContext &&
        g_adl2AdapterCount(g_adlContext, &adapterCount) == ADL_OK &&
        adapterCount > 0 && adapterCount <= 64) {
        std::vector<ADLAdapterInfo> adapters(
            static_cast<size_t>(adapterCount));
        for (auto& info : adapters)
            info.iSize = sizeof(ADLAdapterInfo);

        if (g_adl2AdapterInfo(
                g_adlContext, adapters.data(),
                static_cast<int>(adapters.size() *
                                 sizeof(ADLAdapterInfo))) == ADL_OK) {
            for (const auto& adapter : adapters) {
                if (adapter.iPresent && adapter.iExist)
                    g_adlAdapterIndices.push_back(adapter.iAdapterIndex);
            }
        }

        if (!g_adlAdapterIndices.empty()) {
            g_adlUsingAdl2 = true;
            Wh_Log(L"GPU temperature: ADL2 OverdriveN initialized");
            return true;
        }
    }

    // Tear down a partially initialized ADL2 context before legacy fallback.
    if (g_adlContext && g_adl2Destroy)
        g_adl2Destroy(g_adlContext);
    g_adlContext = nullptr;
    g_adlAdapterIndices.clear();

    // Legacy Overdrive5 fallback.
    auto create = reinterpret_cast<ADL_Main_Control_Create_t>(
        GetProcAddress(g_adlModule, "ADL_Main_Control_Create"));
    g_adlDestroy = reinterpret_cast<ADL_Main_Control_Destroy_t>(
        GetProcAddress(g_adlModule, "ADL_Main_Control_Destroy"));
    g_adlAdapterCount = reinterpret_cast<ADL_Adapter_NumberOfAdapters_Get_t>(
        GetProcAddress(g_adlModule, "ADL_Adapter_NumberOfAdapters_Get"));
    g_adlAdapterInfo = reinterpret_cast<ADL_Adapter_AdapterInfo_Get_t>(
        GetProcAddress(g_adlModule, "ADL_Adapter_AdapterInfo_Get"));
    g_adlTemperatureGet = reinterpret_cast<ADL_Overdrive5_Temperature_Get_t>(
        GetProcAddress(g_adlModule, "ADL_Overdrive5_Temperature_Get"));

    adapterCount = 0;
    if (!create || !g_adlDestroy || !g_adlAdapterCount || !g_adlAdapterInfo ||
        !g_adlTemperatureGet || create(AdlAlloc, 1) != ADL_OK ||
        g_adlAdapterCount(&adapterCount) != ADL_OK || adapterCount <= 0 ||
        adapterCount > 64) {
        if (g_adlDestroy)
            g_adlDestroy();
        FreeLibrary(g_adlModule);
        g_adlModule = nullptr;
        ResetAdlFunctionPointers();
        Wh_Log(L"GPU temperature: AMD ADL temperature API unavailable");
        return false;
    }

    std::vector<ADLAdapterInfo> adapters(static_cast<size_t>(adapterCount));
    for (auto& info : adapters)
        info.iSize = sizeof(ADLAdapterInfo);

    if (g_adlAdapterInfo(
            adapters.data(),
            static_cast<int>(adapters.size() * sizeof(ADLAdapterInfo))) !=
        ADL_OK) {
        g_adlDestroy();
        FreeLibrary(g_adlModule);
        g_adlModule = nullptr;
        ResetAdlFunctionPointers();
        return false;
    }

    for (const auto& adapter : adapters) {
        if (adapter.iPresent && adapter.iExist)
            g_adlAdapterIndices.push_back(adapter.iAdapterIndex);
    }

    if (g_adlAdapterIndices.empty()) {
        g_adlDestroy();
        FreeLibrary(g_adlModule);
        g_adlModule = nullptr;
        ResetAdlFunctionPointers();
        return false;
    }

    Wh_Log(L"GPU temperature: legacy ADL Overdrive5 initialized");
    return true;
}

void UninitGpuTemperature() {
    if (g_adlUsingAdl2) {
        if (g_adlContext && g_adl2Destroy)
            g_adl2Destroy(g_adlContext);
    } else {
        if (g_adlDestroy)
            g_adlDestroy();
    }

    if (g_adlModule)
        FreeLibrary(g_adlModule);

    g_adlModule = nullptr;
    g_adlInitAttempted = false;
    ResetAdlFunctionPointers();
}

PCWSTR GetGpuTemperatureFormatted() {
    CollectMetricsDataIfNeeded();

    if (g_gpuTemperatureFormatted.formatIndex != g_metricsFormatIndex) {
        int bestMilliC = -1;

        if (InitGpuTemperature()) {
            for (int adapterIndex : g_adlAdapterIndices) {
                int milliC = -1;

                if (g_adlUsingAdl2 && g_adl2TemperatureGet) {
                    // ADL_ODN_TEMPERATURE_TYPE_EDGE = 1. Ryzen iGPUs normally
                    // expose the edge/GPU sensor through this path.
                    constexpr int kEdgeTemperatureType = 1;
                    int rawTemperature = 0;
                    if (g_adl2TemperatureGet(g_adlContext, adapterIndex,
                                             kEdgeTemperatureType,
                                             &rawTemperature) == ADL_OK &&
                        rawTemperature > 0) {
                        // ADL2 OverdriveN is documented/implemented by drivers
                        // in millidegrees C. Keep a defensive conversion for a
                        // driver returning plain degrees.
                        milliC = rawTemperature < 1000
                                     ? rawTemperature * 1000
                                     : rawTemperature;
                    }
                }

                // If OverdriveN didn't return a valid sensor for this adapter,
                // try Overdrive5 when the export exists.
                if (milliC <= 0 && g_adlTemperatureGet) {
                    ADLTemperature temp{sizeof(ADLTemperature), 0};
                    if (g_adlTemperatureGet(adapterIndex, 0, &temp) == ADL_OK &&
                        temp.iTemperature > 0) {
                        milliC = temp.iTemperature;
                    }
                }

                if (milliC > 1000 && milliC < 150000)
                    bestMilliC = (std::max)(bestMilliC, milliC);
            }
        }

        if (bestMilliC > 0) {
            const int celsius = (bestMilliC + 500) / 1000;
            swprintf_s(g_gpuTemperatureFormatted.buffer, L"%d°C", celsius);
        } else {
            // Sensor/API genuinely unavailable. Never fabricate a temperature.
            wcscpy_s(g_gpuTemperatureFormatted.buffer, L"N/A");
        }

        g_gpuTemperatureFormatted.formatIndex = g_metricsFormatIndex;
    }

    return g_gpuTemperatureFormatted.buffer;
}

