bool RecreateTextResources() {
    HRESULT hr;

    // Create top line text format.
    PCWSTR topFontFamily = g_settings.topLine.fontFamily.get();
    if (!topFontFamily || !*topFontFamily) {
        topFontFamily = L"Segoe UI";
    }

    hr = g_dwriteFactory->CreateTextFormat(
        topFontFamily, nullptr,
        GetDWriteFontWeight(g_settings.topLine.fontWeight),
        g_settings.topLine.fontItalic ? DWRITE_FONT_STYLE_ITALIC
                                      : DWRITE_FONT_STYLE_NORMAL,
        DWRITE_FONT_STRETCH_NORMAL,
        (FLOAT)g_settings.topLine.fontSize * g_dpiScale, L"",
        &g_topLineTextFormat);
    if (FAILED(hr)) {
        Wh_Log(L"CreateTextFormat (top) failed: 0x%08X", hr);
        return false;
    }

    g_topLineTextFormat->SetTextAlignment(DWRITE_TEXT_ALIGNMENT_CENTER);

    // Create top line text brush.
    D2D1_COLOR_F topTextColor = D2D1::ColorF(
        g_settings.topLine.colorR / 255.0f, g_settings.topLine.colorG / 255.0f,
        g_settings.topLine.colorB / 255.0f, 1.0f);
    hr = g_dc->CreateSolidColorBrush(topTextColor, &g_topLineTextBrush);
    if (FAILED(hr)) {
        Wh_Log(L"CreateSolidColorBrush (top) failed: 0x%08X", hr);
        return false;
    }

    // Create bottom line text format.
    PCWSTR bottomFontFamily = g_settings.bottomLine.fontFamily.get();
    if (!bottomFontFamily || !*bottomFontFamily) {
        bottomFontFamily = L"Segoe UI";
    }

    hr = g_dwriteFactory->CreateTextFormat(
        bottomFontFamily, nullptr,
        GetDWriteFontWeight(g_settings.bottomLine.fontWeight),
        g_settings.bottomLine.fontItalic ? DWRITE_FONT_STYLE_ITALIC
                                         : DWRITE_FONT_STYLE_NORMAL,
        DWRITE_FONT_STRETCH_NORMAL,
        (FLOAT)g_settings.bottomLine.fontSize * g_dpiScale, L"",
        &g_bottomLineTextFormat);
    if (FAILED(hr)) {
        Wh_Log(L"CreateTextFormat (bottom) failed: 0x%08X", hr);
        return false;
    }

    g_bottomLineTextFormat->SetTextAlignment(DWRITE_TEXT_ALIGNMENT_CENTER);

    // Create bottom line text brush.
    D2D1_COLOR_F bottomTextColor =
        D2D1::ColorF(g_settings.bottomLine.colorR / 255.0f,
                     g_settings.bottomLine.colorG / 255.0f,
                     g_settings.bottomLine.colorB / 255.0f, 1.0f);
    hr = g_dc->CreateSolidColorBrush(bottomTextColor, &g_bottomLineTextBrush);
    if (FAILED(hr)) {
        Wh_Log(L"CreateSolidColorBrush (bottom) failed: 0x%08X", hr);
        return false;
    }

    // Create background brush.
    if (g_settings.backgroundEnabled) {
        const float backgroundOpacity =
            (100 - g_settings.backgroundTransparency) / 100.0f;
        D2D1_COLOR_F backgroundColor =
            D2D1::ColorF(g_settings.backgroundColorR / 255.0f,
                         g_settings.backgroundColorG / 255.0f,
                         g_settings.backgroundColorB / 255.0f,
                         backgroundOpacity);
        hr = g_dc->CreateSolidColorBrush(backgroundColor, &g_backgroundBrush);
        if (FAILED(hr)) {
            Wh_Log(L"CreateSolidColorBrush (background) failed: 0x%08X", hr);
            return false;
        }

        // Create blur effect.
        if (g_settings.backgroundBlur > 0) {
            CaptureWallpaperBitmap();
            if (g_wallpaperBitmap) {
                hr = g_dc->CreateEffect(kCLSID_D2D1GaussianBlur, &g_blurEffect);
                if (SUCCEEDED(hr)) {
                    g_blurEffect->SetInput(0, g_wallpaperBitmap.Get());
                    g_blurEffect->SetValue(
                        0,  // D2D1_GAUSSIANBLUR_PROP_STANDARD_DEVIATION
                        (FLOAT)g_settings.backgroundBlur);
                    g_blurEffect->SetValue(
                        2,           // D2D1_GAUSSIANBLUR_PROP_BORDER_MODE
                        (UINT32)1);  // D2D1_BORDER_MODE_HARD
                } else {
                    Wh_Log(L"CreateEffect (blur) failed: 0x%08X", hr);
                }
            }
        }

        if (g_settings.animationEnabled && g_settings.animationGlowSize > 0) {
            D2D1_COLOR_F glowColor =
                D2D1::ColorF(g_settings.animationGlowColorR / 255.0f,
                             g_settings.animationGlowColorG / 255.0f,
                             g_settings.animationGlowColorB / 255.0f, 1.0f);
            hr = g_dc->CreateSolidColorBrush(glowColor, &g_animationGlowBrush);
            if (FAILED(hr)) {
                Wh_Log(L"CreateSolidColorBrush (animation glow) failed: 0x%08X", hr);
            }
        }
    }

    return true;
}

bool ResizeSwapChain(UINT width, UINT height) {
    if (!g_swapChain || !g_dc) {
        return false;
    }

    Wh_Log(L"ResizeSwapChain: %ux%u", width, height);

    // Release the current render target.
    g_dc->SetTarget(nullptr);

    // Resize swap chain buffers.
    HRESULT hr =
        g_swapChain->ResizeBuffers(0, width, height, DXGI_FORMAT_UNKNOWN, 0);
    if (FAILED(hr)) {
        Wh_Log(L"ResizeBuffers failed: 0x%08X", hr);
        return false;
    }

    // Recreate bitmap target from resized swap chain surface.
    ComPtr<IDXGISurface2> surface;
    hr = g_swapChain->GetBuffer(0, IID_PPV_ARGS(&surface));
    if (FAILED(hr)) {
        Wh_Log(L"GetBuffer failed: 0x%08X", hr);
        return false;
    }

    D2D1_BITMAP_PROPERTIES1 bitmapProperties = {};
    bitmapProperties.pixelFormat.alphaMode = D2D1_ALPHA_MODE_PREMULTIPLIED;
    bitmapProperties.pixelFormat.format = DXGI_FORMAT_B8G8R8A8_UNORM;
    bitmapProperties.bitmapOptions =
        D2D1_BITMAP_OPTIONS_TARGET | D2D1_BITMAP_OPTIONS_CANNOT_DRAW;

    ComPtr<ID2D1Bitmap1> targetBitmap;
    hr = g_dc->CreateBitmapFromDxgiSurface(surface.Get(), bitmapProperties,
                                           &targetBitmap);
    if (FAILED(hr)) {
        Wh_Log(L"CreateBitmapFromDxgiSurface failed: 0x%08X", hr);
        return false;
    }

    g_dc->SetTarget(targetBitmap.Get());
    return true;
}

bool IsRunningOnBattery() {
    SYSTEM_POWER_STATUS ps{};
    return GetSystemPowerStatus(&ps) && ps.ACLineStatus == 0;
}

bool IsFullscreenForegroundApp() {
    HWND foreground = GetForegroundWindow();
    if (!foreground || foreground == g_overlayWnd || foreground == GetShellWindow()) {
        return false;
    }

    if (IsIconic(foreground) || !IsWindowVisible(foreground)) {
        return false;
    }

    RECT windowRect{};
    if (!GetWindowRect(foreground, &windowRect)) {
        return false;
    }

    HMONITOR monitor = MonitorFromWindow(foreground, MONITOR_DEFAULTTONEAREST);
    MONITORINFO mi{.cbSize = sizeof(mi)};
    if (!GetMonitorInfo(monitor, &mi)) {
        return false;
    }

    // Allow a tiny tolerance for borderless-fullscreen windows whose invisible
    // resize borders extend a few pixels beyond the monitor rectangle.
    constexpr int kTolerance = 3;
    return windowRect.left <= mi.rcMonitor.left + kTolerance &&
           windowRect.top <= mi.rcMonitor.top + kTolerance &&
           windowRect.right >= mi.rcMonitor.right - kTolerance &&
           windowRect.bottom >= mi.rcMonitor.bottom - kTolerance;
}

bool IsReducedPowerRendering() {
    if (!g_settings.adaptiveFps) {
        return false;
    }
    if (g_settings.pauseWhenFullscreen && IsFullscreenForegroundApp()) {
        return true;
    }
    if (g_settings.batterySaver && IsRunningOnBattery()) {
        return true;
    }
    return false;
}

void InvalidateTextLayoutCache() {
    g_cachedTopLayout.Reset();
    g_cachedBottomLayout.Reset();
    g_cachedTopText.clear();
    g_cachedBottomText.clear();
    g_cachedLayoutWidth = 0;
    g_cachedLayoutHeight = 0;
    g_cachedTopWidth = g_cachedTopHeight = 0.0f;
    g_cachedBottomWidth = g_cachedBottomHeight = 0.0f;
}

bool EnsureTextLayout(PCWSTR text,
                      IDWriteTextFormat* textFormat,
                      UINT surfaceWidth,
                      UINT surfaceHeight,
                      std::wstring* cachedText,
                      ComPtr<IDWriteTextLayout>* cachedLayout,
                      float* cachedWidth,
                      float* cachedHeight) {
    if (!text || !*text || !textFormat) {
        cachedLayout->Reset();
        cachedText->clear();
        *cachedWidth = 0.0f;
        *cachedHeight = 0.0f;
        return false;
    }

    const bool surfaceChanged = g_cachedLayoutWidth != surfaceWidth ||
                                g_cachedLayoutHeight != surfaceHeight;
    if (*cachedLayout && !surfaceChanged && *cachedText == text) {
        return true;
    }

    ComPtr<IDWriteTextLayout> layout;
    HRESULT hr = g_dwriteFactory->CreateTextLayout(
        text, static_cast<UINT32>(wcslen(text)), textFormat,
        static_cast<FLOAT>(surfaceWidth), static_cast<FLOAT>(surfaceHeight),
        &layout);
    if (FAILED(hr) || !layout) {
        return false;
    }

    DWRITE_TEXT_METRICS metrics{};
    if (FAILED(layout->GetMetrics(&metrics))) {
        return false;
    }
    layout->SetMaxWidth(metrics.width);

    *cachedText = text;
    *cachedLayout = std::move(layout);
    *cachedWidth = metrics.width;
    *cachedHeight = metrics.height;
    return true;
}

void RenderOverlay() {
    if (g_unloading || !g_dc || !g_swapChain || !g_dwriteFactory) {
        return;
    }

    RECT rc;
    GetClientRect(g_overlayWnd, &rc);
    UINT width = rc.right - rc.left;
    UINT height = rc.bottom - rc.top;

    g_dc->BeginDraw();
    g_dc->Clear(D2D1::ColorF(0, 0, 0, 0));

    // Update format time.
    GetLocalTime(&g_formatTime);
    g_formatIndex++;

    // Format both lines.
    PCWSTR rawTopText = g_settings.topLine.text.get();
    WCHAR formattedTopText[1024] = {};
    if (rawTopText && *rawTopText) {
        FormatLine(formattedTopText, ARRAYSIZE(formattedTopText), rawTopText);
    }

    PCWSTR rawBottomText = g_settings.bottomLine.text.get();
    WCHAR formattedBottomText[1024] = {};
    if (rawBottomText && *rawBottomText) {
        FormatLine(formattedBottomText, ARRAYSIZE(formattedBottomText),
                   rawBottomText);
    }

    bool hasTopLine = *formattedTopText && g_topLineTextFormat;
    bool hasBottomLine = *formattedBottomText && g_bottomLineTextFormat;

    if (hasTopLine || hasBottomLine) {
        HMONITOR monitor = GetMonitorById(g_settings.monitor - 1);
        if (!monitor) {
            monitor = MonitorFromPoint({0, 0}, MONITOR_DEFAULTTONEAREST);
        }

        MONITORINFO monitorInfo{.cbSize = sizeof(monitorInfo)};
        if (GetMonitorInfo(monitor, &monitorInfo)) {
            // Convert from virtual screen coordinates to overlay window
            // coordinates. The overlay window covers the entire virtual screen,
            // so we need to offset by the virtual screen origin.
            int virtualScreenX = GetSystemMetrics(SM_XVIRTUALSCREEN);
            int virtualScreenY = GetSystemMetrics(SM_YVIRTUALSCREEN);

            RECT workArea;
            workArea.left = monitorInfo.rcWork.left - virtualScreenX;
            workArea.top = monitorInfo.rcWork.top - virtualScreenY;
            workArea.right = monitorInfo.rcWork.right - virtualScreenX;
            workArea.bottom = monitorInfo.rcWork.bottom - virtualScreenY;

            // Reuse DirectWrite layouts while the text is unchanged. This is
            // especially important during animation frames, where only the card
            // position/halo changes.
            if (g_cachedLayoutWidth != width || g_cachedLayoutHeight != height) {
                InvalidateTextLayoutCache();
                g_cachedLayoutWidth = width;
                g_cachedLayoutHeight = height;
            }

            if (hasTopLine) {
                EnsureTextLayout(formattedTopText, g_topLineTextFormat.Get(), width,
                                 height, &g_cachedTopText, &g_cachedTopLayout,
                                 &g_cachedTopWidth, &g_cachedTopHeight);
            } else {
                g_cachedTopLayout.Reset();
                g_cachedTopText.clear();
                g_cachedTopWidth = g_cachedTopHeight = 0.0f;
            }

            if (hasBottomLine) {
                EnsureTextLayout(formattedBottomText,
                                 g_bottomLineTextFormat.Get(), width, height,
                                 &g_cachedBottomText, &g_cachedBottomLayout,
                                 &g_cachedBottomWidth, &g_cachedBottomHeight);
            } else {
                g_cachedBottomLayout.Reset();
                g_cachedBottomText.clear();
                g_cachedBottomWidth = g_cachedBottomHeight = 0.0f;
            }

            auto topLayout = g_cachedTopLayout;
            auto bottomLayout = g_cachedBottomLayout;
            float topWidth = g_cachedTopWidth, topHeight = g_cachedTopHeight;
            float bottomWidth = g_cachedBottomWidth, bottomHeight = g_cachedBottomHeight;

            // Calculate combined dimensions and apply user scale.
            float lineGap = (hasTopLine && hasBottomLine)
                                ? g_settings.lineGap * g_dpiScale
                                : 0.0f;
            const float widgetScale = g_settings.scalePercent / 100.0f;
            float totalWidth = std::max(topWidth, bottomWidth) * widgetScale;
            float totalHeight = (topHeight + lineGap + bottomHeight) * widgetScale;
            float workWidth = (float)(workArea.right - workArea.left);
            float workHeight = (float)(workArea.bottom - workArea.top);

            // Position presets: 9 intuitive anchors plus fine pixel offsets.
            const float leftX = static_cast<float>(workArea.left);
            const float centerX = workArea.left + (workWidth - totalWidth) * 0.5f;
            const float rightX = workArea.right - totalWidth;
            const float topY = static_cast<float>(workArea.top);
            const float centerY = workArea.top + (workHeight - totalHeight) * 0.5f;
            const float bottomY = workArea.bottom - totalHeight;

            float blockX = centerX;
            float blockY = topY;
            switch (g_settings.positionPreset) {
                case WidgetPosition::TopLeft:      blockX = leftX;   blockY = topY;    break;
                case WidgetPosition::TopCenter:    blockX = centerX; blockY = topY;    break;
                case WidgetPosition::TopRight:     blockX = rightX;  blockY = topY;    break;
                case WidgetPosition::CenterLeft:   blockX = leftX;   blockY = centerY; break;
                case WidgetPosition::Center:       blockX = centerX; blockY = centerY; break;
                case WidgetPosition::CenterRight:  blockX = rightX;  blockY = centerY; break;
                case WidgetPosition::BottomLeft:   blockX = leftX;   blockY = bottomY; break;
                case WidgetPosition::BottomCenter: blockX = centerX; blockY = bottomY; break;
                case WidgetPosition::BottomRight:  blockX = rightX;  blockY = bottomY; break;
            }
            blockX += g_settings.positionOffsetX * g_dpiScale;
            blockY += g_settings.positionOffsetY * g_dpiScale;

            float animationPulse = 0.0f;
            if (g_settings.animationEnabled) {
                const double period = (std::max)(400, g_settings.animationPeriodMs);
                const double phase =
                    (static_cast<double>(GetTickCount64() % static_cast<ULONGLONG>(period)) /
                     period) * 6.2831853071795864769;
                animationPulse = static_cast<float>(0.5 + 0.5 * std::sin(phase));
                blockY += static_cast<float>(std::sin(phase)) *
                          g_settings.animationFloatAmount * g_dpiScale;
            }

            // Scale the complete card around its top-left corner. The position
            // calculation above already uses scaled dimensions.
            D2D1_MATRIX_3X2_F previousTransform;
            g_dc->GetTransform(&previousTransform);
            g_dc->SetTransform(
                D2D1::Matrix3x2F::Scale(widgetScale, widgetScale,
                                       D2D1::Point2F(blockX, blockY)) *
                previousTransform);

            // Convert total dimensions back to unscaled drawing coordinates.
            const float drawTotalWidth = std::max(topWidth, bottomWidth);
            const float drawTotalHeight = topHeight + lineGap + bottomHeight;

            // Draw background if enabled.
            if (g_backgroundBrush) {
                float padding =
                    (float)g_settings.backgroundPadding * g_dpiScale;
                float bgWidth = drawTotalWidth + 2 * padding;
                float bgHeight = drawTotalHeight + 2 * padding;
                float radius = std::min(
                    (float)g_settings.backgroundCornerRadius * g_dpiScale,
                    std::min(bgWidth, bgHeight) / 2.0f);
                D2D1_ROUNDED_RECT backgroundRect = D2D1::RoundedRect(
                    D2D1::RectF(blockX - padding, blockY - padding,
                                blockX + drawTotalWidth + padding,
                                blockY + drawTotalHeight + padding),
                    radius, radius);

                // Draw blurred wallpaper behind background.
                if (g_blurEffect) {
                    ComPtr<ID2D1RoundedRectangleGeometry> clipGeo;
                    g_d2dFactory->CreateRoundedRectangleGeometry(backgroundRect,
                                                                 &clipGeo);
                    if (clipGeo) {
                        g_dc->PushLayer(
                            D2D1::LayerParameters(D2D1::InfiniteRect(),
                                                  clipGeo.Get()),
                            nullptr);
                        g_dc->DrawImage(g_blurEffect.Get());
                        g_dc->PopLayer();
                    }
                }

                // Soft animated halo around the glass card. Multiple thin
                // strokes are used instead of a heavy blur effect to keep GPU
                // cost low inside explorer.exe.
                if (g_animationGlowBrush && g_settings.animationGlowSize > 0 &&
                    !(g_settings.batterySaver && IsRunningOnBattery())) {
                    const float maxOpacity =
                        (g_settings.animationGlowColorA / 255.0f) *
                        (0.25f + animationPulse * 0.55f);
                    const int glowSteps =
                        (std::max)(1, (std::min)(8, g_settings.animationGlowSize));
                    for (int i = glowSteps; i >= 1; --i) {
                        float expand = i * 1.6f * g_dpiScale;
                        D2D1_ROUNDED_RECT glowRect = D2D1::RoundedRect(
                            D2D1::RectF(backgroundRect.rect.left - expand,
                                       backgroundRect.rect.top - expand,
                                       backgroundRect.rect.right + expand,
                                       backgroundRect.rect.bottom + expand),
                            radius + expand, radius + expand);
                        g_animationGlowBrush->SetOpacity(
                            maxOpacity * (1.0f - (i - 1.0f) / (glowSteps + 1.0f)));
                        g_dc->DrawRoundedRectangle(glowRect,
                                                   g_animationGlowBrush.Get(),
                                                   1.0f * g_dpiScale);
                    }
                    g_animationGlowBrush->SetOpacity(1.0f);
                }

                g_dc->FillRoundedRectangle(backgroundRect,
                                           g_backgroundBrush.Get());

            }

            // Draw top line.
            if (topLayout) {
                float topX = blockX + (drawTotalWidth - topWidth) / 2.0f;
                float topY = blockY;

                float opacity = g_settings.topLine.colorA / 255.0f;
                g_dc->PushLayer(
                    D2D1::LayerParameters(D2D1::InfiniteRect(), nullptr,
                                          D2D1_ANTIALIAS_MODE_PER_PRIMITIVE,
                                          D2D1::IdentityMatrix(), opacity),
                    nullptr);

                g_dc->DrawTextLayout(D2D1::Point2F(topX, topY), topLayout.Get(),
                                     g_topLineTextBrush.Get(),
                                     D2D1_DRAW_TEXT_OPTIONS_ENABLE_COLOR_FONT);

                g_dc->PopLayer();
            }

            // Draw bottom line.
            if (bottomLayout) {
                float bottomX = blockX + (drawTotalWidth - bottomWidth) / 2.0f;
                float bottomY = blockY + topHeight + lineGap;

                float opacity = g_settings.bottomLine.colorA / 255.0f;
                g_dc->PushLayer(
                    D2D1::LayerParameters(D2D1::InfiniteRect(), nullptr,
                                          D2D1_ANTIALIAS_MODE_PER_PRIMITIVE,
                                          D2D1::IdentityMatrix(), opacity),
                    nullptr);

                g_dc->DrawTextLayout(D2D1::Point2F(bottomX, bottomY),
                                     bottomLayout.Get(),
                                     g_bottomLineTextBrush.Get(),
                                     D2D1_DRAW_TEXT_OPTIONS_ENABLE_COLOR_FONT);

                g_dc->PopLayer();
            }

            g_dc->SetTransform(previousTransform);
        }
    }

    g_dc->EndDraw();
    g_swapChain->Present(1, 0);
}

////////////////////////////////////////////////////////////////////////////////
// Refresh timer

UINT GetNextUpdateTimeout() {
    SYSTEMTIME time;
    GetLocalTime(&time);

    // Add a small extra delay to make sure we are past the second/minute
    // change.
    constexpr UINT kExtraDelayMs = 200;

    // Animation uses a lightweight render cadence. Metrics themselves remain
    // throttled by refreshInterval, so a 20 FPS animation doesn't query PDH at
    // 20 FPS.
    if (g_settings.animationEnabled) {
        if (g_settings.adaptiveFps && g_settings.pauseWhenFullscreen &&
            IsFullscreenForegroundApp()) {
            // One refresh per second is enough to keep the clock/metrics current
            // while making the overlay practically idle during games.
            return 1000;
        }
        if (IsReducedPowerRendering()) {
            return (UINT)(std::max)(100, (std::min)(1000, g_settings.idleFrameMs));
        }
        return (UINT)(std::max)(16, (std::min)(250, g_settings.animationFrameMs));
    }

    // GPU temperature is a local sensor and refreshes once per second.
    // Only %weather% depends on the asynchronous wttr.in loading state.
    if (g_settings.showSeconds || g_systemMetricsUsed || g_temperatureUsed ||
        (g_weatherUsed && !g_weatherLoaded)) {
        return 1000 - time.wMilliseconds + kExtraDelayMs;
    }

    // No seconds or system metrics - refresh every minute.
    return (60 - time.wSecond) * 1000 - time.wMilliseconds + kExtraDelayMs;
}

void ScheduleNextUpdate() {
    if (!g_overlayWnd) {
        return;
    }

    UINT timeout = GetNextUpdateTimeout();
    SetTimer(g_overlayWnd, TIMER_ID_OVERLAY_REFRESH, timeout, nullptr);
}

void HandleDisplayChange() {
    Wh_Log(L"HandleDisplayChange");

    if (!g_overlayWnd) {
        return;
    }

    HWND hWorkerW = GetParent(g_overlayWnd);
    if (!hWorkerW) {
        return;
    }

    // Resize overlay window to match WorkerW.
    RECT rc;
    GetWindowRect(hWorkerW, &rc);
    SetWindowPos(g_overlayWnd, nullptr, 0, 0, rc.right - rc.left,
                 rc.bottom - rc.top, SWP_NOZORDER | SWP_NOACTIVATE);

    // Check if DPI changed and recreate resources if needed.
    HMONITOR monitor = GetMonitorById(g_settings.monitor - 1);
    if (!monitor) {
        monitor = MonitorFromPoint({0, 0}, MONITOR_DEFAULTTONEAREST);
    }
    float newDpiScale = GetMonitorDpiScale(monitor);
    if (newDpiScale != g_dpiScale) {
        Wh_Log(L"DPI changed: %.2f -> %.2f", g_dpiScale, newDpiScale);
        ReleaseSwapChainResources();
        GetClientRect(g_overlayWnd, &rc);
        CreateSwapChainResources(rc.right - rc.left, rc.bottom - rc.top);
        RenderOverlay();
    }

    // Schedule a delayed wallpaper recapture so the system has time to
    // repaint the wallpaper at the new resolution.
    if (g_messageWnd && g_settings.backgroundEnabled &&
        g_settings.backgroundBlur > 0) {
        SetTimer(g_messageWnd, TIMER_ID_MSG_WALLPAPER_REFRESH, 500, nullptr);
    }
}

// Forward declarations.
void CreateOverlayWindow();
void ApplySettingsChanged();

LRESULT CALLBACK OverlayWndProc(HWND hWnd,
                                UINT uMsg,
                                WPARAM wParam,
                                LPARAM lParam) {
    switch (uMsg) {
        case WM_TIMER:
            if (!g_unloading && wParam == TIMER_ID_OVERLAY_REFRESH) {
                RenderOverlay();
                ScheduleNextUpdate();
                return 0;
            }
            break;

        case WM_WINDOWPOSCHANGED: {
            const WINDOWPOS* wp = (const WINDOWPOS*)lParam;
            if (!(wp->flags & SWP_NOSIZE) && !g_unloading) {
                Wh_Log(L"WM_WINDOWPOSCHANGED: %dx%d", wp->cx, wp->cy);
                ResizeSwapChain(wp->cx, wp->cy);
                RenderOverlay();
            }
            break;
        }

        case WM_DESTROY:
            Wh_Log(L"Overlay WM_DESTROY");
            ReleaseSwapChainResources();
            g_overlayWnd = nullptr;
            // Schedule recreation if not unloading.
            if (!g_unloading && g_messageWnd) {
                SetTimer(g_messageWnd, TIMER_ID_MSG_RECREATE_OVERLAY, 200,
                         nullptr);
            }
            return 0;

        case WM_APP_CLEANUP:
            DestroyWindow(hWnd);
            return 0;

        case WM_APP_SETTINGS_CHANGED:
            ApplySettingsChanged();
            return 0;
    }
    return DefWindowProc(hWnd, uMsg, wParam, lParam);
}

LRESULT CALLBACK MessageWndProc(HWND hWnd,
                                UINT uMsg,
                                WPARAM wParam,
                                LPARAM lParam) {
    switch (uMsg) {
        case WM_HOTKEY:
            if (wParam == HOTKEY_ID_TRANSPARENCY &&
                g_settings.transparencyHotkey && !g_unloading) {
                static constexpr int kLevels[] = {15, 30, 45, 60, 75, 90};
                int current = g_settings.backgroundTransparency;
                int next = kLevels[0];
                for (int level : kLevels) {
                    if (level > current) {
                        next = level;
                        break;
                    }
                }
                if (current >= kLevels[ARRAYSIZE(kLevels) - 1])
                    next = kLevels[0];

                g_settings.backgroundTransparency = next;

                if (g_overlayWnd) {
                    ReleaseTextResources();
                    RecreateTextResources();
                    RenderOverlay();
                }
                return 0;
            }
            break;

        case WM_DISPLAYCHANGE:
            Wh_Log(L"WM_DISPLAYCHANGE received");
            if (!g_unloading) {
                // Delay handling to allow WorkerW to resize first.
                SetTimer(hWnd, TIMER_ID_MSG_DISPLAY_CHANGE, 200, nullptr);
            }
            return 0;

        case WM_SETTINGCHANGE: {
            if (g_overlayWnd && !g_unloading && g_settings.backgroundEnabled &&
                g_settings.backgroundBlur > 0) {
                FILETIME ft = GetWallpaperFileTime();
                if (CompareFileTime(&ft, &g_lastWallpaperTime) != 0) {
                    SetTimer(hWnd, TIMER_ID_MSG_WALLPAPER_REFRESH, 2000,
                             nullptr);
                }
            }
            return 0;
        }

        case WM_TIMER:
            if (g_unloading) {
                return 0;
            }
            if (wParam == TIMER_ID_MSG_DISPLAY_CHANGE) {
                KillTimer(hWnd, TIMER_ID_MSG_DISPLAY_CHANGE);
                HandleDisplayChange();
            } else if (wParam == TIMER_ID_MSG_RECREATE_OVERLAY) {
                KillTimer(hWnd, TIMER_ID_MSG_RECREATE_OVERLAY);
                Wh_Log(L"Recreating overlay window");
                CreateOverlayWindow();
            } else if (wParam == TIMER_ID_MSG_WALLPAPER_REFRESH) {
                KillTimer(hWnd, TIMER_ID_MSG_WALLPAPER_REFRESH);
                if (g_overlayWnd && g_settings.backgroundEnabled &&
                    g_settings.backgroundBlur > 0) {
                    ReleaseTextResources();
                    RecreateTextResources();
                    RenderOverlay();
                }
            }
            return 0;

        case WM_DESTROY:
            UnregisterHotKey(hWnd, HOTKEY_ID_TRANSPARENCY);
            g_messageWnd = nullptr;
            return 0;

        case WM_APP_CLEANUP:
            DestroyWindow(hWnd);
            return 0;
    }
    return DefWindowProc(hWnd, uMsg, wParam, lParam);
}

////////////////////////////////////////////////////////////////////////////////
// Overlay window management

bool g_overlayClassRegistered = false;

bool RegisterOverlayWindowClass() {
    if (g_overlayClassRegistered) {
        return true;
    }

    WNDCLASS wc = {};
    wc.lpfnWndProc = OverlayWndProc;
    wc.hInstance = GetCurrentModuleHandle();
    wc.lpszClassName = OVERLAY_WINDOW_CLASS;
    if (!RegisterClass(&wc)) {
        Wh_Log(L"Failed to register overlay window class: %u", GetLastError());
        return false;
    }

    g_overlayClassRegistered = true;
    return true;
}

void UnregisterOverlayWindowClass() {
    if (g_overlayClassRegistered) {
        UnregisterClass(OVERLAY_WINDOW_CLASS, GetCurrentModuleHandle());
        g_overlayClassRegistered = false;
    }
}

bool EnsureLazyInitialized() {
    if (g_lazyInitialized.exchange(true)) {
        return g_initSucceeded;
    }

    g_systemMetricsUsed = IsSystemMetricsUsed();
    g_weatherUsed = IsWeatherUsed();
    g_temperatureUsed = IsTemperatureUsed();

    RunDxgiWorkaroundForExplorerPatcher();

    if (!InitDirectX()) {
        Wh_Log(L"InitDirectX failed");
        return false;
    }

    if (g_systemMetricsUsed) {
        InitMetrics();
    }

    WeatherUpdateThreadInit();
    if (g_temperatureUsed) {
        InitGpuTemperature();
    }

    g_initSucceeded = true;
    return true;
}

void CreateOverlayWindow() {
    if (g_overlayWnd) {
        return;
    }

    if (!EnsureLazyInitialized()) {
        return;
    }

    HWND hWorkerW = GetWorkerW();
    if (!hWorkerW) {
        Wh_Log(L"Failed to find WorkerW");
        return;
    }

    if (!RegisterOverlayWindowClass()) {
        return;
    }

    HINSTANCE hInstance = GetCurrentModuleHandle();

    RECT rc;
    GetWindowRect(hWorkerW, &rc);
    int width = rc.right - rc.left;
    int height = rc.bottom - rc.top;

    g_overlayWnd = CreateWindowEx(
        WS_EX_NOREDIRECTIONBITMAP | WS_EX_TRANSPARENT | WS_EX_NOACTIVATE,
        OVERLAY_WINDOW_CLASS, nullptr, WS_CHILD | WS_VISIBLE, 0, 0, width,
        height, hWorkerW, nullptr, hInstance, nullptr);

    if (!g_overlayWnd) {
        Wh_Log(L"Failed to create overlay window: %u", GetLastError());
        return;
    }

    if (CreateSwapChainResources(width, height)) {
        RenderOverlay();
        ScheduleNextUpdate();
    }
}

