COLORREF ParseHex(std::wstring value, COLORREF fallback) {
    if (!value.empty() && value[0] == L'#') {
        value.erase(value.begin());
    }

    if (value.size() != 6) {
        return fallback;
    }

    wchar_t* end = nullptr;
    unsigned long rgb = wcstoul(value.c_str(), &end, 16);
    if (!end || *end != L'\0') {
        return fallback;
    }

    return RGB(
        (rgb >> 16) & 0xFF,
        (rgb >> 8) & 0xFF,
        rgb & 0xFF);
}

void RecreateReplacementBrush() {
    if (g_replacementBrush) {
        DeleteObject(g_replacementBrush);
        g_replacementBrush = nullptr;
    }

    if (CreateSolidBrush_Original) {
        g_replacementBrush =
            CreateSolidBrush_Original(g_settings.replacement);
    } else {
        g_replacementBrush =
            CreateSolidBrush(g_settings.replacement);
    }
}

