    s.tint = ParseHex(
        GetStringSettingCopy(L"Appearance.TintColor"),
        RGB(0x10, 0x13, 0x18));

    s.replacement = ParseHex(
        GetStringSettingCopy(L"Appearance.ReplacementPanelColor"),
        RGB(0x10, 0x13, 0x18));

    s.roundedCorners =
        Wh_GetIntSetting(L"Appearance.RoundedCorners") != 0;

    s.replaceLightBrushes =
        Wh_GetIntSetting(L"WhitePanelFix.ReplaceLightBrushes") != 0;

    s.replaceSystemWindowColors =
        Wh_GetIntSetting(L"WhitePanelFix.ReplaceSystemWindowColors") != 0;

    s.lightThreshold =
        ClampInt(Wh_GetIntSetting(L"WhitePanelFix.LightThreshold"), 160, 250);

    s.transparentStandardLists =
        Wh_GetIntSetting(L"WhitePanelFix.TransparentStandardLists") != 0;

    s.reapply =
        Wh_GetIntSetting(L"Behavior.Reapply") != 0;

    const std::wstring ms = GetStringSettingCopy(L"Behavior.ReapplyMs");
    s.reapplyMs =
        ms.empty() ? 500 : ClampInt(_wtoi(ms.c_str()), 250, 5000);

    g_settings = s;

    RecreateReplacementBrush();
}

bool IsLightColor(COLORREF color) {
    const int r = GetRValue(color);
    const int g = GetGValue(color);
    const int b = GetBValue(color);

    return r >= g_settings.lightThreshold &&
           g >= g_settings.lightThreshold &&
           b >= g_settings.lightThreshold;
}

bool IsOurWindow(HWND hwnd) {
    if (!hwnd) {
        return false;
    }

    DWORD pid = 0;
    GetWindowThreadProcessId(hwnd, &pid);
    return pid == g_pid;
}

bool IsOurDc(HDC hdc) {
    if (!hdc) {
        return false;
    }

    HWND hwnd = WindowFromDC(hdc);
    if (!hwnd) {
        return false;
    }

    return IsOurWindow(GetAncestor(hwnd, GA_ROOT));
}

bool IsTopLevelOurWindow(HWND hwnd) {
    if (!IsOurWindow(hwnd) || !IsWindowVisible(hwnd)) {
        return false;
    }

    LONG_PTR style = GetWindowLongPtrW(hwnd, GWL_STYLE);
    return (style & WS_CHILD) == 0;
}

// -----------------------------------------------------------------------------
// Strong white-panel correction.
// -----------------------------------------------------------------------------

HBRUSH WINAPI CreateSolidBrush_Hook(COLORREF color) {
    if (g_settings.replaceLightBrushes &&
        IsLightColor(color)) {
        return CreateSolidBrush_Original(g_settings.replacement);
    }

    return CreateSolidBrush_Original(color);
}

DWORD WINAPI GetSysColor_Hook(int index) {
    if (g_settings.replaceSystemWindowColors) {
        switch (index) {
            case COLOR_WINDOW:
            case COLOR_BTNFACE:
            case COLOR_MENU:
            case COLOR_INFOBK:
                return g_settings.replacement;
        }
    }

    return GetSysColor_Original(index);
}

HBRUSH WINAPI GetSysColorBrush_Hook(int index) {
    if (g_settings.replaceSystemWindowColors) {
        switch (index) {
            case COLOR_WINDOW:
            case COLOR_BTNFACE:
            case COLOR_MENU:
            case COLOR_INFOBK:
                if (g_replacementBrush) {
                    return g_replacementBrush;
                }
                break;
        }
    }

    return GetSysColorBrush_Original(index);
}

int WINAPI FillRect_Hook(
    HDC hdc,
    const RECT* rect,
    HBRUSH brush) {

    if (g_settings.replaceLightBrushes &&
        IsOurDc(hdc) &&
        brush) {

        LOGBRUSH lb{};
        if (GetObjectW(brush, sizeof(lb), &lb) == sizeof(lb) &&
            lb.lbStyle == BS_SOLID &&
            IsLightColor(lb.lbColor) &&
            g_replacementBrush) {

            return FillRect_Original(
                hdc,
                rect,
                g_replacementBrush);
        }
    }

    return FillRect_Original(hdc, rect, brush);
}

BOOL WINAPI PatBlt_Hook(
    HDC hdc,
    int x,
    int y,
    int width,
    int height,
    DWORD rop) {

    if (g_settings.replaceLightBrushes &&
        IsOurDc(hdc) &&
        rop == PATCOPY &&
        g_replacementBrush) {

        HBRUSH current = reinterpret_cast<HBRUSH>(
            GetCurrentObject(hdc, OBJ_BRUSH));

        if (current) {
            LOGBRUSH lb{};
            if (GetObjectW(current, sizeof(lb), &lb) == sizeof(lb) &&
                lb.lbStyle == BS_SOLID &&
                IsLightColor(lb.lbColor)) {

                HBRUSH old = reinterpret_cast<HBRUSH>(
                    SelectObject(hdc, g_replacementBrush));

                BOOL result = PatBlt_Original(
                    hdc, x, y, width, height, rop);

                SelectObject(hdc, old);
                return result;
            }
        }
    }

    return PatBlt_Original(hdc, x, y, width, height, rop);
}

BOOL WINAPI ExtTextOutW_Hook(
    HDC hdc,
    int x,
    int y,
    UINT options,
    const RECT* rect,
    LPCWSTR text,
    UINT count,
    const INT* dx) {

    if (IsOurDc(hdc)) {
        // Never let text drawing create an opaque white rectangle.
        if (options & ETO_OPAQUE) {
            COLORREF bk = GetBkColor(hdc);
            if (IsLightColor(bk)) {
                options &= ~ETO_OPAQUE;
                SetBkMode(hdc, TRANSPARENT);
            }
        }
    }

    return ExtTextOutW_Original(
        hdc,
        x,
        y,
        options,
        rect,
        text,
        count,
        dx);
}

// -----------------------------------------------------------------------------
// Window material.
// -----------------------------------------------------------------------------

DWORD MakeGradientColor() {
    const BYTE a = static_cast<BYTE>(
        ClampInt(g_settings.acrylicOpacity, 0, 100) * 255 / 100);

    const BYTE r = GetRValue(g_settings.tint);
    const BYTE g = GetGValue(g_settings.tint);
    const BYTE b = GetBValue(g_settings.tint);

    // AABBGGRR
    return
        (static_cast<DWORD>(a) << 24) |
        (static_cast<DWORD>(b) << 16) |
        (static_cast<DWORD>(g) << 8) |
        static_cast<DWORD>(r);
}

void ApplyDwmMaterial(HWND hwnd) {
    if (!hwnd) {
        return;
    }

    if (g_setWindowCompositionAttribute) {
        ACCENT_POLICY policy{};
        policy.AccentState = ACCENT_ENABLE_ACRYLICBLURBEHIND;
        policy.AccentFlags = 0x20 | 0x40 | 0x80 | 0x100;
        policy.GradientColor = MakeGradientColor();

        WINDOWCOMPOSITIONATTRIBDATA data{};
        data.Attrib = WCA_ACCENT_POLICY;
        data.pvData = &policy;
        data.cbData = sizeof(policy);

        g_setWindowCompositionAttribute(hwnd, &data);
    }

    MARGINS margins{-1, -1, -1, -1};
    DwmExtendFrameIntoClientArea(hwnd, &margins);

    BOOL dark = TRUE;

    constexpr DWORD DWMWA_USE_IMMERSIVE_DARK_MODE_OLD = 19;
    constexpr DWORD DWMWA_USE_IMMERSIVE_DARK_MODE_NEW = 20;

    DwmSetWindowAttribute(
        hwnd,
        DWMWA_USE_IMMERSIVE_DARK_MODE_NEW,
        &dark,
        sizeof(dark));

    DwmSetWindowAttribute(
        hwnd,
        DWMWA_USE_IMMERSIVE_DARK_MODE_OLD,
        &dark,
        sizeof(dark));

    if (g_settings.roundedCorners) {
        constexpr DWORD DWMWA_WINDOW_CORNER_PREFERENCE = 33;
        int preference = 2; // DWMWCP_ROUND

        DwmSetWindowAttribute(
            hwnd,
            DWMWA_WINDOW_CORNER_PREFERENCE,
            &preference,
            sizeof(preference));
    }
}

void ApplyWindowOpacity(HWND hwnd) {
    LONG_PTR ex = GetWindowLongPtrW(hwnd, GWL_EXSTYLE);

    if ((ex & WS_EX_LAYERED) == 0) {
        SetWindowLongPtrW(
            hwnd,
            GWL_EXSTYLE,
            ex | WS_EX_LAYERED);

        SetWindowPos(
            hwnd,
            nullptr,
            0, 0, 0, 0,
            SWP_NOMOVE |
            SWP_NOSIZE |
            SWP_NOZORDER |
            SWP_NOACTIVATE |
            SWP_FRAMECHANGED);
    }

    BYTE alpha = static_cast<BYTE>(
        ClampInt(g_settings.windowOpacity, 0, 100) * 255 / 100);

    SetLayeredWindowAttributes(
        hwnd,
        0,
        alpha,
        LWA_ALPHA);
}

void ApplyUniformChildOpacity(HWND hwnd) {
    if (!hwnd || !IsOurWindow(hwnd)) {
        return;
    }

    // Do not alter tiny utility/tooltip windows.
    RECT rc{};
    if (!GetWindowRect(hwnd, &rc)) {
        return;
    }

    const int w = rc.right - rc.left;
    const int h = rc.bottom - rc.top;
    if (w < 20 || h < 14) {
        return;
    }

    wchar_t cls[128]{};
    GetClassNameW(hwnd, cls, ARRAYSIZE(cls));

    // These are the controls that most commonly retain an opaque backing
    // surface in IObit's old custom skin.
    const bool panelLike =
        _wcsicmp(cls, L"Static") == 0 ||
        _wcsicmp(cls, L"SysListView32") == 0 ||
        _wcsicmp(cls, L"SysTreeView32") == 0 ||
        _wcsicmp(cls, L"ListBox") == 0;

    if (!panelLike) {
        return;
    }

    LONG_PTR ex = GetWindowLongPtrW(hwnd, GWL_EXSTYLE);
    if ((ex & WS_EX_LAYERED) == 0) {
        SetWindowLongPtrW(hwnd, GWL_EXSTYLE, ex | WS_EX_LAYERED);
    }

    // Same alpha family as the parent, slightly stronger for text legibility.
    const int childPercent = ClampInt(g_settings.windowOpacity + 6, 40, 100);
    const BYTE alpha =
        static_cast<BYTE>(childPercent * 255 / 100);

    SetLayeredWindowAttributes(hwnd, 0, alpha, LWA_ALPHA);
}

void FixStandardChild(HWND hwnd) {
    if (!IsOurWindow(hwnd)) {
        return;
    }

    ApplyUniformChildOpacity(hwnd);

    if (!g_settings.transparentStandardLists) {
        return;
    }

    wchar_t cls[128]{};
    GetClassNameW(hwnd, cls, ARRAYSIZE(cls));

    if (_wcsicmp(cls, L"SysListView32") == 0) {
        SetWindowTheme(hwnd, L"DarkMode_Explorer", nullptr);

        ListView_SetBkColor(hwnd, g_settings.replacement);
        ListView_SetTextBkColor(hwnd, CLR_NONE);
        ListView_SetTextColor(hwnd, RGB(238, 238, 238));

        HWND header = ListView_GetHeader(hwnd);
        if (header) {
            SetWindowTheme(header, L"DarkMode_Explorer", nullptr);
        }
    } else if (_wcsicmp(cls, L"SysTreeView32") == 0) {
        SetWindowTheme(hwnd, L"DarkMode_Explorer", nullptr);
        TreeView_SetBkColor(hwnd, g_settings.replacement);
        TreeView_SetTextColor(hwnd, RGB(238, 238, 238));
    }
}

BOOL CALLBACK EnumChildProc(HWND hwnd, LPARAM) {
    FixStandardChild(hwnd);
    return TRUE;
}

void ApplyToTopLevel(HWND hwnd) {
    if (!IsTopLevelOurWindow(hwnd)) {
        return;
    }

    ApplyDwmMaterial(hwnd);
    ApplyWindowOpacity(hwnd);

    EnumChildWindows(hwnd, EnumChildProc, 0);

    RedrawWindow(
        hwnd,
        nullptr,
        nullptr,
        RDW_INVALIDATE |
        RDW_ERASE |
        RDW_ALLCHILDREN |
        RDW_UPDATENOW);
}

BOOL CALLBACK EnumTopProc(HWND hwnd, LPARAM) {
    ApplyToTopLevel(hwnd);
    return TRUE;
}

void ApplyAll() {
    EnumWindows(EnumTopProc, 0);
}

DWORD WINAPI WorkerProc(void*) {
    Sleep(400);

    while (g_running.load()) {
        ApplyAll();

        Sleep(
            g_settings.reapply
                ? g_settings.reapplyMs
                : 2000);
    }

    return 0;
}

} // namespace

BOOL Wh_ModInit() {
    g_pid = GetCurrentProcessId();

    HMODULE user32 = GetModuleHandleW(L"user32.dll");
    if (user32) {
        g_setWindowCompositionAttribute =
            reinterpret_cast<SetWindowCompositionAttribute_t>(
                GetProcAddress(
                    user32,
                    "SetWindowCompositionAttribute"));
    }

    // Hook before LoadSettings so RecreateReplacementBrush can use Original.
    Wh_SetFunctionHook(
        reinterpret_cast<void*>(CreateSolidBrush),
        reinterpret_cast<void*>(CreateSolidBrush_Hook),
        reinterpret_cast<void**>(&CreateSolidBrush_Original));

    Wh_SetFunctionHook(
        reinterpret_cast<void*>(GetSysColor),
        reinterpret_cast<void*>(GetSysColor_Hook),
        reinterpret_cast<void**>(&GetSysColor_Original));

    Wh_SetFunctionHook(
        reinterpret_cast<void*>(GetSysColorBrush),
        reinterpret_cast<void*>(GetSysColorBrush_Hook),
        reinterpret_cast<void**>(&GetSysColorBrush_Original));

    Wh_SetFunctionHook(
        reinterpret_cast<void*>(FillRect),
        reinterpret_cast<void*>(FillRect_Hook),
        reinterpret_cast<void**>(&FillRect_Original));

    Wh_SetFunctionHook(
        reinterpret_cast<void*>(PatBlt),
        reinterpret_cast<void*>(PatBlt_Hook),
        reinterpret_cast<void**>(&PatBlt_Original));

    Wh_SetFunctionHook(
        reinterpret_cast<void*>(ExtTextOutW),
        reinterpret_cast<void*>(ExtTextOutW_Hook),
        reinterpret_cast<void**>(&ExtTextOutW_Original));

    LoadSettings();

    g_running = true;

    g_thread = CreateThread(
        nullptr,
        0,
        WorkerProc,
        nullptr,
        0,
        nullptr);

    if (!g_thread) {
        g_running = false;
        return FALSE;
    }

    Wh_Log(L"IObit Unlocker Full Translucent v4 activo.");
    return TRUE;
}

void Wh_ModSettingsChanged() {
    LoadSettings();
    ApplyAll();
}

void Wh_ModUninit() {
    g_running = false;

    if (g_thread) {
        WaitForSingleObject(g_thread, 3000);
        CloseHandle(g_thread);
        g_thread = nullptr;
    }

    if (g_replacementBrush) {
        DeleteObject(g_replacementBrush);
        g_replacementBrush = nullptr;
    }
}

