}

// Exclusión dura: no aplicar el mod a Microsoft Office, AMD Software: Adrenalin
// ni a procesos cuyo nombre contenga "pirata". Esta comprobación ocurre antes
// de cargar ajustes o instalar hooks, por lo que esos procesos quedan intactos.
BOOL IsHardExcludedProcess()
{
    std::wstring proc = GetCurrProcStr();

    static const wchar_t* kOfficeProcesses[] = {
        L"winword.exe",
        L"excel.exe",
        L"powerpnt.exe",
        L"outlook.exe",
        L"msaccess.exe",
        L"onenote.exe",
        L"mspub.exe",
        L"visio.exe",
        L"lync.exe",
        L"officeclicktorun.exe",
        L"officec2rclient.exe",
        L"integratedoffice.exe",
        L"firstrun.exe",
        L"protocolhandler.exe",
        L"olk.exe",              // Outlook nuevo
        L"msoasb.exe",
        L"msosync.exe",
        L"msouc.exe",
        L"officesvcmgr.exe",
        L"sdxhelper.exe",
        L"msoadfsb.exe",
        L"ai.exe",               // asistente de Office
        L"excelcnv.exe",
        L"graph.exe",
        L"msqry32.exe",          // Microsoft Query (Excel)
        L"selfcert.exe"          // firma de macros VBA
    };

    for (const wchar_t* officeProc : kOfficeProcesses) {
        if (proc == officeProc)
            return TRUE;
    }

    // AMD Software: Adrenalin Edition.
    // La interfaz principal se ejecuta como RadeonSoftware.exe.
    // Se excluye antes de instalar hooks para conservar su diseño original.
    if (proc == L"radeonsoftware.exe")
        return TRUE;

    // Aether OS: otros programas que dibujan su propia ventana, usan sus
    // propios efectos o son sensibles al rendimiento. Se dejan intactos.
    static const wchar_t* kAetherExcludedProcesses[] = {
        // AMD Software: Adrenalin y sus componentes
        L"amdrsserv.exe",
        L"amdrssrcext.exe",
        L"amdow.exe",
        L"radeonsettings.exe",
        L"cncmd.exe",
        L"amdsoftwareinstaller.exe",
        L"amdsoftwarecompanion.exe",
        L"amdsplashscreen.exe",
        // Juegos y lanzadores
        L"steam.exe",
        L"steamwebhelper.exe",
        L"gameoverlayui.exe",
        L"gameoverlayui64.exe",
        L"launcher.exe",          // Rockstar Games Launcher
        L"rockstarservice.exe",
        L"socialclubhelper.exe",
        L"playgtav.exe",
        L"gta5.exe",
        L"gta5_enhanced.exe",
        L"pcsx2-qt.exe",
        L"pcsx2.exe",
        L"pcsx2-qtx64-avx2.exe",
        // Grabación de pantalla
        L"bdcam.exe",             // Bandicam
        L"obs64.exe",
        // Programas con sus propios efectos o su propio dibujo
        L"windowsterminal.exe",
        L"code.exe",              // VS Code
        L"claude.exe",
        L"chatgpt.exe",
        L"mspcmanager.exe",       // Microsoft PC Manager
        L"windhawk.exe"
    };
    for (const wchar_t* excludedProc : kAetherExcludedProcesses) {
        if (proc == excludedProc)
            return TRUE;
    }

    // También se protegen ejecutables cuyo nombre contenga "pirata".
    if (proc.find(L"pirata") != std::wstring::npos)
        return TRUE;

    return FALSE;
}

enum AccentColorShade
{
    SystemAccentColorLight3,
    SystemAccentColorLight2,
    SystemAccentColorLight1,
    SystemAccentColorBase,
    SystemAccentColorDark1,
    SystemAccentColorDark2,
    SystemAccentColorDark3,
    Unused,
    AccentColorCount
};

class AccentPalette
{
public:
    std::array<COLORREF, AccentColorCount> Colors;
    BOOL LoadAccentPalette();
    AccentPalette()
    {
        LoadAccentPalette();
    }
};
AccentPalette g_AccentPalette;

BOOL AccentPalette::LoadAccentPalette()
{
    const LPCWSTR kAccentRegPath = L"Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\Accent";
    const LPCWSTR kAccentPaletteValue = L"AccentPalette";

    HKEY hKey;
    if (RegOpenKeyExW(HKEY_CURRENT_USER, kAccentRegPath, 0, KEY_READ, &hKey) != ERROR_SUCCESS)
        return FALSE;

    BYTE data[32] = {};
    DWORD dataSize = sizeof(data);
    DWORD type = 0;

    if (RegQueryValueExW(hKey, kAccentPaletteValue, nullptr, &type, data, &dataSize) != ERROR_SUCCESS || type != REG_BINARY || dataSize < AccentColorCount * 4)
    {
        RegCloseKey(hKey);
        return FALSE;
    }

    RegCloseKey(hKey);

    for (INT i = 0; i < AccentColorCount; ++i)
    {
        DWORD color = *reinterpret_cast<DWORD*>(&data[i * 4]);
        Colors[i] = color;
    }
    return TRUE;
}

BOOL GetAccentColor(COLORREF& outColor)
{
    // In some programs, e.g. snippingtool.exe, the default blue accent color is used instead of the Windows theme with DwmGetColorizationColor.
    // Use the immersive color API if available, fall back to DwmGetColorizationColor
    // https://github.com/ALTaleX531/TranslucentFlyouts/blob/017970cbac7b77758ab6217628912a8d551fcf7c/Common/ThemeHelper.hpp#L278
    static const auto s_GetImmersiveColorFromColorSetEx{reinterpret_cast<DWORD(WINAPI*)(DWORD dwImmersiveColorSet, DWORD dwImmersiveColorType, BOOL bIgnoreHighContrast, DWORD dwHighContrastCacheMode)>(GetProcAddress(GetModuleHandleW(L"UxTheme.dll"), MAKEINTRESOURCEA(95)))};
    static const auto s_GetImmersiveColorTypeFromName{reinterpret_cast<DWORD(WINAPI*)(LPCWSTR name)>(GetProcAddress(GetModuleHandleW(L"UxTheme.dll"), MAKEINTRESOURCEA(96)))};
    static const auto s_GetImmersiveUserColorSetPreference{reinterpret_cast<DWORD(WINAPI*)(BOOL bForceCheckRegistry, BOOL bSkipCheckOnFail)>(GetProcAddress(GetModuleHandleW(L"UxTheme.dll"), MAKEINTRESOURCEA(98)))};

    COLORREF AccentClr{ 0 };
    BOOL opaque = FALSE;
    
    if (s_GetImmersiveColorFromColorSetEx && s_GetImmersiveColorTypeFromName && s_GetImmersiveUserColorSetPreference) 
    {
        AccentClr = s_GetImmersiveColorFromColorSetEx(
            s_GetImmersiveUserColorSetPreference(FALSE, FALSE),
            s_GetImmersiveColorTypeFromName(L"ImmersiveStartHoverBackground"),
            TRUE,
            0
        );
        outColor = RGB((AccentClr & 0xFF), (AccentClr >> 8) & 0xFF, (AccentClr >> 16) & 0xFF);
        return TRUE;
    }
    else if (SUCCEEDED(DwmGetColorizationColor(&AccentClr, &opaque)))
    {
        outColor = RGB((AccentClr >> 16) & 0xFF, (AccentClr >> 8) & 0xFF,  AccentClr & 0xFF);
        return TRUE;
    }
    else
    {
        outColor = DWMWA_COLOR_DEFAULT;
        return FALSE;
    }
}

