    }

    VOID DeleteHDC(HDC& hDC)
    {
        if (hDC) {
            DeleteObject((HBITMAP)GetCurrentObject(hDC, OBJ_BITMAP));
            DeleteDC(std::exchange(hDC, nullptr));
