BOOL WINAPI HookedFillRect(HDC hdc, LPCRECT lprc, HBRUSH hbr)
{    
    ULONG_PTR pseudoSystemBrush = (ULONG_PTR)hbr - 1;
    if (pseudoSystemBrush <= 30)
