// Normalizes a path: flips slashes, trims trailing slashes, lowercases.
std::wstring NormalizeRule(std::wstring path) 
{
    if (path.empty()) return path;

    // 1. Normalize slashes
    for (auto& ch : path)
        if (ch == L'/') 
            ch = L'\\';

    // 2. Trim trailing slashes (now guaranteed to be backslashes)
    while (!path.empty() && path.back() == L'\\')
        path.pop_back();
    
    if (path.empty()) 
        return path;

    // 3. Lowercase
    LCMapStringEx(LOCALE_NAME_USER_DEFAULT, LCMAP_LOWERCASE, 
                  path.c_str(), (INT)path.length(), &path[0], (INT)path.length(), 
                  nullptr, nullptr, 0);

    return path;
}

struct CurrentProcessInfo {
    std::wstring fullPath;   // (e.g. c:\windows\system32\notepad.exe)
    std::wstring fileName;   // (e.g. notepad.exe)
    std::wstring directory;  // (e.g. c:\windows\system32)
};

CurrentProcessInfo GetCurrentProcessInfo() 
{
    WCHAR modulePath[MAX_PATH];
    GetModuleFileNameW(nullptr, modulePath, MAX_PATH);

    CurrentProcessInfo info;
    info.fullPath = modulePath;

    // FIX 1: Strip Windows long path prefix if present, otherwise string matches fail
    if (info.fullPath.find(L"\\\\?\\") == 0) {
        info.fullPath.erase(0, 4);
    }

    // FIX 2: Process paths can occasionally contain forward slashes depending on launch method.
    for (auto& ch : info.fullPath) {
        if (ch == L'/') ch = L'\\';
    }

    // Lowercase the main string once
    LCMapStringEx(LOCALE_NAME_USER_DEFAULT, LCMAP_LOWERCASE, 
                  info.fullPath.c_str(), (INT)info.fullPath.length(), 
                  &info.fullPath[0], (INT)info.fullPath.length(), 
                  nullptr, nullptr, 0);

    // Extract substrings cleanly 
    size_t pos = info.fullPath.find_last_of(L'\\');
    if (pos != std::wstring::npos) {
        info.fileName = info.fullPath.substr(pos + 1);
        info.directory = info.fullPath.substr(0, pos);
    } else {
        info.fileName = info.fullPath;
        info.directory = L""; 
    }

    return info;
}

bool MatchesProcessRule(const std::wstring& rawEntry, const CurrentProcessInfo& proc) 
{
    std::wstring entry = NormalizeRule(rawEntry);
    if (entry.empty()) return false;

    // Exact full path or directory match
    if (entry == proc.fullPath || entry == proc.directory)
        return true;

    // Bare name, e.g. "mspaint.exe"
    if (entry.find(L'\\') == std::wstring::npos) {
        return entry == proc.fileName;
    }

    // FIX 3: Subfolder match. Use .find() == 0 for a bulletproof "starts_with" check.
    std::wstring prefix = entry + L"\\";
    if (proc.fullPath.find(prefix) == 0)
        return true;

    return false;
}

VOID LoadWindowProcessRules()
{
    CurrentProcessInfo currProc = GetCurrentProcessInfo();

    for (INT i = 0;; i++) 
    {
        auto program = WindhawkUtils::StringSetting(Wh_GetStringSetting(L"RuledPrograms[%d].target", i));
        
        if (!*program)
            break; 

        if (MatchesProcessRule(program.get(), currProc))
        {
            g_settings.FillBg = Wh_GetIntSetting(L"RuledPrograms[%d].RenderingMod.ThemeBackground", i);
            
            BOOL globalSetting_CustomTheme = Wh_GetIntSetting(L"RenderingMod.ThemeBackground");
            if (!globalSetting_CustomTheme)
                GenerateTextAlphaGammaLUT();
            
            g_settings.AccentColorize = Wh_GetIntSetting(L"RuledPrograms[%d].RenderingMod.AccentColorControls", i);
            if (g_settings.AccentColorize)
                g_settings.AccentColorize = GetAccentColor(g_settings.AccentColor);
            
            BOOL globalSetting_SetSysColorAPI = Wh_GetIntSetting(L"RenderingMod.Syscolors");

            // Reset system colors to default values if the system color setting is disabled for the specific ruled process
            if (!g_settings.FillBg && globalSetting_SetSysColorAPI)
                g_DefaultSysColors = TRUE;
            
            // Hook all necessary APIs to restore system colors when SetSysColors API has been executed by the mod
            if (g_DefaultSysColors) {
                WindhawkUtils::SetFunctionHook(GetSysColor, HookedGetSysColor, &GetSysColor_orig);
                WindhawkUtils::SetFunctionHook(GetSysColorBrush, HookedGetSysColorBrush, &GetSysColorBrush_orig);               
                WindhawkUtils::SetFunctionHook(FillRect, HookedFillRect, &FillRect_orig);
                User32Hooks(g_settings.SetSystemColors);
            }   

            auto strStyle = WindhawkUtils::StringSetting(Wh_GetStringSetting(L"RuledPrograms[%d].BackgroundEffects.type", i));
            if (0 == wcscmp(strStyle, L"acrylicblur"))
                g_settings.BgType = g_settings.AccentBlurBehind;
            else if (0 == wcscmp(strStyle, L"acrylicsystem"))
                g_settings.BgType = g_settings.AcrylicSystemBackdrop;
            else if (0 == wcscmp(strStyle, L"mica"))
                g_settings.BgType = g_settings.Mica;
            else if (0 == wcscmp(strStyle, L"mica_tabbed"))
                g_settings.BgType = g_settings.MicaAlt;
            else 
                g_settings.BgType = g_settings.Default;

            GetColorSetting(WindhawkUtils::StringSetting(Wh_GetStringSetting(L"RuledPrograms[%d].BackgroundEffects.AccentBlurBehind", i)), g_settings.AccentBlurBehindClr);
            
            break;
        }
    }
}

VOID LoadSettings()
{
    g_settings.AccentColorize = Wh_GetIntSetting(L"RenderingMod.AccentColorControls");
    if (g_settings.AccentColorize)
       g_settings.AccentColorize = GetAccentColor(g_settings.AccentColor);

    g_settings.FillBg = Wh_GetIntSetting(L"RenderingMod.ThemeBackground");
    if (g_settings.FillBg)
        GenerateTextAlphaGammaLUT();
    
    g_settings.SetSystemColors = Wh_GetIntSetting(L"RenderingMod.Syscolors");
    // SetSysColors API available only in theme customization
    if (g_settings.SetSystemColors && g_settings.FillBg)
        ColorizeSysColors();
    
    auto strStyle = WindhawkUtils::StringSetting(Wh_GetStringSetting(L"BackgroundEffects.type"));
    if (0 == wcscmp(strStyle, L"acrylicblur"))
        g_settings.BgType = g_settings.AccentBlurBehind;
    else if (0 == wcscmp(strStyle, L"acrylicsystem"))
        g_settings.BgType = g_settings.AcrylicSystemBackdrop;
    else if (0 == wcscmp(strStyle, L"mica"))
        g_settings.BgType = g_settings.Mica;
    else if (0 == wcscmp(strStyle, L"mica_tabbed"))
        g_settings.BgType = g_settings.MicaAlt;
    else 
        g_settings.BgType = g_settings.Default;
    
    GetColorSetting(WindhawkUtils::StringSetting(Wh_GetStringSetting(L"BackgroundEffects.AccentBlurBehind")), g_settings.AccentBlurBehindClr);

    g_settings.FlyoutsEffects = Wh_GetIntSetting(L"FlyoutsEffects");
        
    LoadWindowProcessRules();
    
    ApplyHooks();
}

BOOL Wh_ModInit(VOID) 
{
    // Don't install any hooks or apply visual/system-color changes in hard-excluded apps.
    if (IsHardExcludedProcess()) {
        Wh_Log(L"Proceso excluido: no se instalarán hooks ni se aplicarán cambios visuales.");
        return TRUE;
    }

    if (InExplorerProcess())
        g_explorerStylerNoBackgroundEffectAtom = AddAtom(L"WindhawkFileExplorerStylerNoBackgroundEffect");
    if (InTaskManagerProcess())
        g_InsideTaskMgrProc = TRUE;

    LoadSettings();

    HMODULE hModule = GetModuleHandle(L"win32u.dll");
    if (!hModule) 
        return FALSE;
        
    NtUserCreateWindowEx_t pNtUserCreateWindowEx = (NtUserCreateWindowEx_t)GetProcAddress(hModule, "NtUserCreateWindowEx");
    if (!pNtUserCreateWindowEx)
        return FALSE;
    
    WindhawkUtils::SetFunctionHook(pNtUserCreateWindowEx, HookedNtUserCreateWindowEx, &NtUserCreateWindowEx_Original);
    
    return TRUE;
}

VOID Wh_ModAfterInit() 
{
    #ifdef _WIN64
        const size_t OFFSET_SAME_TEB_FLAGS = 0x17EE;
    #else
        const size_t OFFSET_SAME_TEB_FLAGS = 0x0FCA;
    #endif
    BOOL isInitialThread = *(USHORT*)((BYTE*)NtCurrentTeb() + OFFSET_SAME_TEB_FLAGS) & 0x0400;
    if (!isInitialThread)
        ApplyForExistingWindows();
}

VOID Wh_ModUninit(VOID) 
{
    if (g_explorerStylerNoBackgroundEffectAtom)
        DeleteAtom(g_explorerStylerNoBackgroundEffectAtom);
     
    g_settings.Unload = TRUE;
    if (g_settings.FillBg && g_d2dFactory)
        g_d2dFactory->Release();
    
    if (g_settings.SetSystemColors)
        RevertSysColors();

    for (size_t i = 0; i < g_themeCachedDefaultSysColorBrushes.size(); i++) {
        HBRUSH& brushCustom = g_themeCachedCustomSysColorBrushes[i];
        HBRUSH& brushDefault = g_themeCachedDefaultSysColorBrushes[i];
        if (brushCustom) { 
            DeleteObject(brushCustom); 
            brushCustom = nullptr; 
        }
        if (brushDefault) { 
            DeleteObject(brushDefault); 
            brushDefault = nullptr; 
        }
    }

    ApplyForExistingWindows();
}

BOOL Wh_ModSettingsChanged(BOOL* bReload) 
{
    *bReload = TRUE;
    return TRUE;
}

// ==WindhawkMod==
// @id              win11-power-buttons-fork
// @name            Botones de energía del menú Inicio de Windows 11 - Español
// @description     Agrega botones configurables de un clic para Apagar, Reiniciar, Cerrar sesión, Suspender, Hibernar y Bloquear en el menú Inicio de Windows 11.
// @version         1.1.0-es
// @author          Hakuuyosei
// @github          https://github.com/ahzvenol
// @include         StartMenuExperienceHost.exe
// @include         explorer.exe
// @architecture    x86-64
// @compilerOptions -lcomctl32 -lole32 -loleaut32 -lruntimeobject -Wl,--export-all-symbols -luser32 -lwtsapi32 -lpowrprof
// ==/WindhawkMod==

// ==WindhawkModReadme==
/*
# Botones de energía del menú Inicio de Windows 11

Reemplaza el botón de energía tradicional del menú Inicio por botones directos
y configurables para:

- Apagar
- Reiniciar
- Cerrar sesión
- Suspender
- Hibernar
- Bloquear

Puedes elegir qué botones mostrar, el orden y su alineación.
*/
// ==/WindhawkModReadme==

// ==WindhawkModSettings==
/*
- alignment: right
  $name: Alineación
  $description: Alinea el grupo de botones dentro del panel de navegación.
  $options:
    - left: Izquierda
    - center: Centro
    - right: Derecha

- confirm_before_action: false
  $name: Confirmar antes de ejecutar
  $description: Muestra una ventana de confirmación antes de realizar una acción de energía.

- buttons: [sleep, signout, restart, shutdown]
  $name: Botones y orden
  $description: Elige qué botones mostrar y en qué orden. Los elementos repetidos se ignoran.
  $options:
    - shutdown: Apagar
    - restart: Reiniciar
    - signout: Cerrar sesión
    - sleep: Suspender
    - hibernate: Hibernar
    - lock: Bloquear
*/
// ==/WindhawkModSettings==

#include <atomic>
#include <string>
#include <vector>
#include <mutex>
#include <set>
#include <cwchar>
#include <cwctype>

#include <windows.h>
#include <powrprof.h>

#undef GetCurrentTime

#include <winrt/base.h>
#include <winrt/Windows.Foundation.h>
#include <winrt/Windows.Foundation.Collections.h>
#include <winrt/Windows.UI.Core.h>
#include <winrt/Windows.UI.Xaml.h>
#include <winrt/Windows.UI.Xaml.Controls.h>
#include <winrt/Windows.UI.Xaml.Controls.Primitives.h>
#include <winrt/Windows.UI.Xaml.Media.h>
#include <winrt/Windows.System.h>

namespace wux = winrt::Windows::UI::Xaml;
namespace wuxc = winrt::Windows::UI::Xaml::Controls;
namespace wuxm = winrt::Windows::UI::Xaml::Media;
namespace wu = winrt::Windows::UI;
namespace wuc = winrt::Windows::UI::Core;

// Global state flags
static std::atomic<bool> g_initialized = false;
static std::atomic<bool> g_unloading = false;
static std::atomic<bool> g_buttonsInjected = false;
static std::atomic<bool> g_monitoringActive = false;
static std::atomic<bool> g_forceRebuild = false;

static std::mutex g_settingsMutex;

// ============================================================================
// Settings Management
// ============================================================================

struct Settings {
    wux::HorizontalAlignment alignment = wux::HorizontalAlignment::Right;
    std::vector<std::wstring> buttonKeywords;
};

static Settings g_settings;

static std::wstring JoinStrings(const std::vector<std::wstring>& v) {
    std::wstring out;
    for (size_t i = 0; i < v.size(); i++) {
        if (i) out += L",";
        out += v[i];
    }
    return out;
}

// Parses Windhawk settings into internal structures
static void LoadSettings() {
    std::lock_guard<std::mutex> lock(g_settingsMutex);

    g_settings.alignment = wux::HorizontalAlignment::Right;
    PCWSTR alignmentStr = Wh_GetStringSetting(L"alignment");

    if (_wcsicmp(alignmentStr, L"left") == 0) {
        g_settings.alignment = wux::HorizontalAlignment::Left;
    } else if (_wcsicmp(alignmentStr, L"center") == 0) {
        g_settings.alignment = wux::HorizontalAlignment::Center;
    }

    Wh_FreeStringSetting(alignmentStr);

    g_settings.buttonKeywords.clear();
    // 'buttons' is defined as an array of strings in settings.
    // Iterates up to a reasonable limit or until an empty/missing entry is encountered.
    for (int i = 0; i < 32; i++) {
        PCWSTR itemStr = Wh_GetStringSetting(L"buttons[%d]", i);
        if (!itemStr || !*itemStr) {
            Wh_FreeStringSetting(itemStr);
            break;
        }

        std::wstring item(itemStr);
        Wh_FreeStringSetting(itemStr);

        if (!item.empty())
            g_settings.buttonKeywords.push_back(std::move(item));
    }

    Wh_Log(L"Ajustes cargados: alineación=%d, confirmar=%d, botones=%s",
           static_cast<int>(g_settings.alignment),
           Wh_GetIntSetting(L"confirm_before_action") != 0,
           JoinStrings(g_settings.buttonKeywords).c_str());
}

// ============================================================================
// Button Configuration
// ============================================================================

enum class PowerAction {
    Shutdown = 0,
    Restart = 1,
    SignOut = 2,
    Sleep = 3,
    Hibernate = 4,
    Lock = 5,
};

struct ButtonDefinition {
    std::wstring keyword;
    PowerAction action;
    const wchar_t* glyph;
};

// Glyphs are from Segoe Fluent Icons.
static const std::vector<ButtonDefinition> g_buttonDefinitions = {
    {L"shutdown",  PowerAction::Shutdown,  L"\uE7E8"},
    {L"restart",   PowerAction::Restart,   L"\uE777"},
    {L"signout",   PowerAction::SignOut,   L"\uF3B1"},
    {L"sleep",     PowerAction::Sleep,     L"\uE708"},
    {L"hibernate", PowerAction::Hibernate, L"\uE823"},
    {L"lock",      PowerAction::Lock,      L"\uE72E"},
};

struct ButtonConfig {
    PowerAction action;
    const wchar_t* glyph;
};

static std::vector<ButtonConfig> g_buttons;

// Maps configuration keywords to actionable button definitions, ensuring uniqueness
static void BuildButtons() {
    std::lock_guard<std::mutex> lock(g_settingsMutex);

    g_buttons.clear();
    std::set<PowerAction> seen;

    for (const auto& keyword : g_settings.buttonKeywords) {
        for (const auto& def : g_buttonDefinitions) {
            if (def.keyword == keyword && seen.insert(def.action).second) {
                g_buttons.push_back({def.action, def.glyph});
                break;
            }
        }
    }
}

// ============================================================================
// Localization
// ============================================================================

static std::wstring GetActionDisplayName(PowerAction action) {
    switch (action) {
        case PowerAction::Shutdown:
            return L"Apagar";
        case PowerAction::Restart:
            return L"Reiniciar";
        case PowerAction::SignOut:
            return L"Cerrar sesión";
        case PowerAction::Sleep:
            return L"Suspender";
        case PowerAction::Hibernate:
            return L"Hibernar";
        case PowerAction::Lock:
            return L"Bloquear";
    }
    return L"";
}

static std::wstring GetConfirmTitle() {
    return L"Confirmar acción de energía";
}

static std::wstring GetConfirmMessage(PowerAction action) {
    return L"¿Seguro que quieres " + GetActionDisplayName(action) + L"?";
}

// ============================================================================
// Cross-Process IPC (Explorer Proxy)
//
// StartMenuExperienceHost.exe runs within a restricted AppContainer sandbox
// and lacks privileges to execute ExitWindowsEx or SetSuspendState.
// To perform these privileged commands, a hidden message-only window is
// injected into Explorer.exe (running with user privileges) to act as a proxy.
// ============================================================================

static const wchar_t* PROXY_WINDOW_CLASS = L"PowerActionProxy_Class";
static const wchar_t* PROXY_WINDOW_NAME  = L"PowerActionProxy_Window";
static const wchar_t* PROXY_MESSAGE_NAME = L"PowerActionProxy_Execute";

static UINT g_proxyMessage = 0;
static HWND g_proxyWindow = NULL;
static HANDLE g_proxyThread = NULL;

static void InitProxyMessage() {
    if (g_proxyMessage == 0) {
        g_proxyMessage = RegisterWindowMessageW(PROXY_MESSAGE_NAME);
    }
}

static bool ConfirmPowerAction(PowerAction action) {
    std::wstring title = GetConfirmTitle();
    std::wstring message = GetConfirmMessage(action);

    int button = MessageBoxW(nullptr, message.c_str(), title.c_str(), MB_ICONQUESTION | MB_YESNO | MB_TOPMOST | MB_SETFOREGROUND);
    return button == IDYES;
}

// Executes the requested power action, acquiring necessary privileges if required
static void PerformPowerAction(PowerAction action) {
    HANDLE hToken = NULL;
    TOKEN_PRIVILEGES tkp{};
    if (OpenProcessToken(GetCurrentProcess(), TOKEN_ADJUST_PRIVILEGES | TOKEN_QUERY, &hToken)) {
        if (LookupPrivilegeValue(NULL, SE_SHUTDOWN_NAME, &tkp.Privileges[0].Luid)) {
            tkp.PrivilegeCount = 1;
            tkp.Privileges[0].Attributes = SE_PRIVILEGE_ENABLED;
            AdjustTokenPrivileges(hToken, FALSE, &tkp, 0, NULL, 0);
        }
        CloseHandle(hToken);
    }

    switch (action) {
        case PowerAction::Shutdown:
            ExitWindowsEx(EWX_SHUTDOWN | EWX_FORCE, SHTDN_REASON_MAJOR_OTHER);
            break;
        case PowerAction::Restart:
            ExitWindowsEx(EWX_REBOOT | EWX_FORCE, SHTDN_REASON_MAJOR_OTHER);
            break;
        case PowerAction::SignOut:
            ExitWindowsEx(EWX_LOGOFF | EWX_FORCE, 0);
            break;
        case PowerAction::Sleep:
            SetSuspendState(FALSE, FALSE, FALSE);
            break;
        case PowerAction::Hibernate:
            SetSuspendState(TRUE, FALSE, FALSE);
            break;
        case PowerAction::Lock:
            LockWorkStation();
            break;
    }
}

static LRESULT CALLBACK ProxyWndProc(HWND hWnd, UINT message, WPARAM wParam, LPARAM lParam) {
    if (message == g_proxyMessage && g_proxyMessage != 0) {
        PowerAction action = (PowerAction)wParam;
        bool needConfirm = Wh_GetIntSetting(L"confirm_before_action") != 0;
        if (!needConfirm || ConfirmPowerAction(action)) {
            PerformPowerAction(action);
        }
        return 0;
    }
    switch (message) {
        case WM_DESTROY:
            g_proxyWindow = NULL;
            PostQuitMessage(0);
            return 0;
    }
    return DefWindowProcW(hWnd, message, wParam, lParam);
}

// Thread function for the hidden proxy window
static DWORD WINAPI ProxyWindowThread(LPVOID) {
    InitProxyMessage();

    WNDCLASSEXW wcex = { sizeof(WNDCLASSEX) };
    wcex.lpfnWndProc = ProxyWndProc;
    wcex.hInstance = GetModuleHandle(NULL);
    wcex.lpszClassName = PROXY_WINDOW_CLASS;

    if (!RegisterClassExW(&wcex)) {
        Wh_Log(L"Proxy: no se pudo registrar la clase, error %lu", GetLastError());
        return 1;
    }

    g_proxyWindow = CreateWindowExW(
        0, PROXY_WINDOW_CLASS, PROXY_WINDOW_NAME,
        0, 0, 0, 0, 0, HWND_MESSAGE,
        NULL, GetModuleHandle(NULL), NULL
    );

    if (!g_proxyWindow) {
        Wh_Log(L"Proxy: no se pudo crear la ventana, error %lu", GetLastError());
        UnregisterClassW(PROXY_WINDOW_CLASS, GetModuleHandle(NULL));
        return 1;
    }

    // Bypass UIPI to allow messages from lower-integrity processes
    ChangeWindowMessageFilterEx(g_proxyWindow, g_proxyMessage, MSGFLT_ALLOW, NULL);

    MSG msg;
    while (GetMessage(&msg, NULL, 0, 0)) {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    UnregisterClassW(PROXY_WINDOW_CLASS, GetModuleHandle(NULL));

    return 0;
}

static void StartProxyThread() {
    g_proxyThread = CreateThread(NULL, 0, ProxyWindowThread, NULL, 0, NULL);
    if (!g_proxyThread) {
        Wh_Log(L"Proxy: no se pudo crear el hilo, error %lu", GetLastError());
    }
}

// Sends a message to the explorer proxy window to execute the command
[[maybe_unused]]
static void SendPowerAction(PowerAction action) {
    InitProxyMessage();

    HWND hProxy = FindWindowW(PROXY_WINDOW_CLASS, PROXY_WINDOW_NAME);
    if (!hProxy) {
        Wh_Log(L"Proxy: no se encontró la ventana. Verifica que explorer.exe esté enganchado.");
        return;
    }

    DWORD proxyProcessId = 0;
    GetWindowThreadProcessId(hProxy, &proxyProcessId);
    AllowSetForegroundWindow(proxyProcessId);

    PostMessageW(hProxy, g_proxyMessage, (WPARAM)action, 0);
}

static bool IsExplorerProcess() {
    WCHAR path[MAX_PATH]{};
    GetModuleFileNameW(NULL, path, MAX_PATH);
    std::wstring p = path;
    for (auto& c : p) c = towlower(c);
    return p.find(L"explorer.exe") != std::wstring::npos;
}

// ============================================================================
// Start Menu UI Injection
// ============================================================================

static const wchar_t* CONTAINER_TAG  = L"PowerButtons_Container";

// Weak references to key UI elements to avoid repeated VisualTree traversal
static winrt::weak_ref<wuxc::Panel> g_parentPanel{ nullptr };
static winrt::weak_ref<wux::FrameworkElement> g_originalPowerButton{ nullptr };
static winrt::weak_ref<wuxc::StackPanel> g_buttonContainer{ nullptr };

static void InjectButtons(wuxc::Panel parentPanel, wux::FrameworkElement originalPowerButton) {
    try {
        Settings currentSettings;
        std::vector<ButtonConfig> currentButtons;
        {
            std::lock_guard<std::mutex> lock(g_settingsMutex);
            currentSettings = g_settings;
            currentButtons = g_buttons;
        }

        // Ensure the native power button remains hidden
        if (originalPowerButton && originalPowerButton.Visibility() != wux::Visibility::Collapsed) {
            originalPowerButton.Visibility(wux::Visibility::Collapsed);
        }

        wuxc::StackPanel container = nullptr;

        // Attempt to retrieve the container from cache
        container = g_buttonContainer.get();
        if (container) {
            // Validate that the cached container is still attached to the target parent
            try {
                auto containerParent = wuxm::VisualTreeHelper::GetParent(container);
                if (!containerParent || containerParent != parentPanel) {
                    container = nullptr;
                    g_buttonContainer = nullptr;
                }
            } catch (...) {
                container = nullptr;
                g_buttonContainer = nullptr;
            }
        }

        // Cache miss: scan children to locate the tagged container
        if (!container) {
            auto children = parentPanel.Children();
            for (uint32_t i = 0; i < children.Size(); i++) {
                auto child = children.GetAt(i);
                if (auto panel = child.try_as<wuxc::StackPanel>()) {
                    auto tag = panel.Tag();
                    if (tag && winrt::unbox_value_or<winrt::hstring>(tag, L"") == CONTAINER_TAG) {
                        container = panel;
                        g_buttonContainer = container;
                        break;
                    }
                }
            }
        }

        // If still not found, create and insert a new container
        if (!container) {
            container = wuxc::StackPanel();
            container.Tag(winrt::box_value(CONTAINER_TAG));
            container.Orientation(wuxc::Orientation::Horizontal);
            container.VerticalAlignment(wux::VerticalAlignment::Center);
            parentPanel.Children().Append(container);
            g_buttonContainer = container;
        }

        // Fast path: if the button count matches and no rebuild is forced,
        // only update layout properties to handle potential style changes.
        if (!g_forceRebuild.exchange(false) &&
            container.Children().Size() == currentButtons.size()) {

            if (container.Visibility() != wux::Visibility::Visible)
                container.Visibility(wux::Visibility::Visible);

            if (container.HorizontalAlignment() != currentSettings.alignment)
                container.HorizontalAlignment(currentSettings.alignment);

            container.Margin({ 0, 0, 0, 0 });
            return;
        }

        // Full rebuild path
        if (container.Visibility() != wux::Visibility::Visible)
            container.Visibility(wux::Visibility::Visible);

        container.HorizontalAlignment(currentSettings.alignment);

        container.Margin({ 0, 0, 0, 0 });

        container.Children().Clear();

        for (size_t i = 0; i < currentButtons.size(); i++) {
            const auto& cfg = currentButtons[i];

            wuxc::Button btn;
            btn.Width(40);
            btn.Height(40);

            // Apply margin only between buttons, not on outer edges
            if (i == currentButtons.size() - 1) {
                btn.Margin({ 0, 0, 0, 0 });
            } else {
                btn.Margin({ 0, 0, 4, 0 });
            }

            // Style the button to be transparent and blend with the Start Menu
            btn.Background(wuxm::SolidColorBrush(wu::Colors::Transparent()));
            btn.BorderThickness({ 0, 0, 0, 0 });
            btn.CornerRadius({ 4, 4, 4, 4 });

            wuxc::FontIcon icon;
            icon.Glyph(cfg.glyph);
            icon.FontFamily(wuxm::FontFamily(L"Segoe Fluent Icons"));
            icon.FontSize(16);
            btn.Content(icon);

            wuxc::ToolTipService::SetToolTip(btn, winrt::box_value(GetActionDisplayName(cfg.action)));

            PowerAction action = cfg.action;
            btn.Click([action](auto&&, auto&&) {
                SendPowerAction(action);
            });

            container.Children().Append(btn);
        }

    } catch (winrt::hresult_error const& ex) {
        Wh_Log(L"Inyección: error WinRT 0x%08X", (unsigned)ex.code());
    } catch (...) {
        Wh_Log(L"Inyección: error desconocido");
    }
}

// Searches the Visual Tree recursively for the element named "PowerButton"
static wux::FrameworkElement FindOriginalPowerButton(wux::DependencyObject parent) {
    if (!parent) return nullptr;

    int count = wuxm::VisualTreeHelper::GetChildrenCount(parent);
    for (int i = 0; i < count; i++) {
        auto child = wuxm::VisualTreeHelper::GetChild(parent, i);

        if (auto fe = child.try_as<wux::FrameworkElement>()) {
            if (fe.Name() == L"PowerButton")
                return fe;
        }

        auto found = FindOriginalPowerButton(child);
        if (found) return found;
    }

    return nullptr;
}

static bool TryInjectButtons() {
    if (g_unloading) return false;

    try {
        auto window = wux::Window::Current();
        if (!window) return false;

        auto content = window.Content();
        if (!content) return false;

        auto powerButton = FindOriginalPowerButton(content);
        if (!powerButton) return false;

        auto parentObj = wuxm::VisualTreeHelper::GetParent(powerButton);
        if (!parentObj) return false;

        auto parentPanel = parentObj.try_as<wuxc::Panel>();
        if (!parentPanel) return false;

        g_parentPanel = parentPanel;
        g_originalPowerButton = powerButton;

        InjectButtons(parentPanel, powerButton);
        g_buttonsInjected = true;

        return true;

    } catch (...) {
        Wh_Log(L"Inyección: excepción al intentar agregar los botones");
        return false;
    }
}

// ============================================================================
// Visibility Monitoring
// Hooks Start Menu window events to trigger injection when UI becomes visible.
// ============================================================================

static winrt::event_token g_visibilityToken{};
static winrt::event_token g_activatedToken{};

static void OnWindowVisible() {
    if (g_unloading) return;

    // Skip if already injected and no setting changes occurred
    if (g_buttonsInjected && !g_forceRebuild) {
        return;
    }

    // Schedule injection on the UI thread at low priority to avoid blocking UI startup
    auto dq = winrt::Windows::System::DispatcherQueue::GetForCurrentThread();
    if (dq) {
        dq.TryEnqueue(winrt::Windows::System::DispatcherQueuePriority::Low, []() {
            if (!g_unloading) {
                TryInjectButtons();
            }
        });
    }
}

static bool StartVisibilityMonitoring() {
    if (g_monitoringActive) return true;

    try {
        wuc::CoreWindow coreWindow = wuc::CoreWindow::GetForCurrentThread();
        if (!coreWindow) return false;

        g_visibilityToken =
            coreWindow.VisibilityChanged([](auto&&, auto&& args) {
                if (args.Visible()) OnWindowVisible();
            });

        g_activatedToken =
            coreWindow.Activated([](auto&&, auto&& args) {
                if (args.WindowActivationState() != wuc::CoreWindowActivationState::Deactivated)
                    OnWindowVisible();
            });

        g_monitoringActive = true;

        // If Start Menu is already visible, trigger immediately
        if (coreWindow.Visible())
            OnWindowVisible();

        return true;
    } catch (...) {
        return false;
    }
}

static void StopVisibilityMonitoring() {
    try {
        // Unregister event handlers
        wuc::CoreWindow coreWindow = wuc::CoreWindow::GetForCurrentThread();
        if (coreWindow) {
            if (g_visibilityToken) {
                coreWindow.VisibilityChanged(g_visibilityToken);
                g_visibilityToken = {};
            }
            if (g_activatedToken) {
                coreWindow.Activated(g_activatedToken);
                g_activatedToken = {};
            }
        }
    } catch (...) {}

    // Cleanup UI: Remove custom buttons and restore original state
    try {
        auto panel = g_parentPanel.get();
        auto container = g_buttonContainer.get();
        auto originalBtn = g_originalPowerButton.get();

        if (panel) {
            // Remove the injected container from the visual tree
            if (container) {
                uint32_t index;
                if (panel.Children().IndexOf(container, index)) {
                    panel.Children().RemoveAt(index);
                }
            }
            // Clear tag/marker if used
            panel.Tag(nullptr);
        }

        // Restore original power button visibility
        if (originalBtn) {
            originalBtn.Visibility(wux::Visibility::Visible);
        }

    } catch (winrt::hresult_error const& ex) {
        Wh_Log(L"Limpieza: error WinRT 0x%08X", (unsigned)ex.code());
    } catch (...) {
        Wh_Log(L"Limpieza: error desconocido");
    }

    // Clear references
    g_parentPanel = nullptr;
    g_originalPowerButton = nullptr;
    g_buttonContainer = nullptr;
    g_monitoringActive = false;
}

// ============================================================================
// Initialization Hooks
// Intercepts window creation to detect the Start Menu's CoreWindow.
// ============================================================================

static const wchar_t* THREAD_CALL_MSG = L"PowerButtons_ThreadCall";

static void InitWithRetry(HWND hwnd);

static void CALLBACK RetryTimerProc(HWND hwnd, UINT, UINT_PTR idEvent, DWORD) {
    KillTimer(hwnd, idEvent);
    InitWithRetry(hwnd);
}

// Attempts to initialize UWP hooks. Retries if the environment isn't ready.
static void InitWithRetry(HWND hwnd) {
    if (!g_initialized.exchange(true)) {
        LoadSettings();
        BuildButtons();
    }

    if (!StartVisibilityMonitoring()) {
        SetTimer(hwnd, 1772058423, 100, RetryTimerProc);
    }
}

// Hook CreateWindowInBand to catch the Windows.UI.Core.CoreWindow creation
using CreateWindowInBand_t = HWND(WINAPI*)(DWORD, LPCWSTR, LPCWSTR, DWORD, int, int, int, int, HWND, HMENU, HINSTANCE, PVOID, DWORD);
static CreateWindowInBand_t CreateWindowInBand_Original;

static HWND WINAPI CreateWindowInBand_Hook(DWORD dwExStyle, LPCWSTR lpClassName, LPCWSTR lpWindowName, DWORD dwStyle,
                                           int X, int Y, int nWidth, int nHeight, HWND hWndParent, HMENU hMenu,
                                           HINSTANCE hInstance, PVOID lpParam, DWORD dwBand) {
    HWND hWnd = CreateWindowInBand_Original(dwExStyle, lpClassName, lpWindowName, dwStyle,
                                           X, Y, nWidth, nHeight, hWndParent, hMenu, hInstance, lpParam, dwBand);
    if (!hWnd) return hWnd;

    // Check for CoreWindow class name efficiently
    if (lpClassName && ((ULONG_PTR)lpClassName & ~(ULONG_PTR)0xffff) != 0 &&
        _wcsicmp(lpClassName, L"Windows.UI.Core.CoreWindow") == 0) {
        InitWithRetry(hWnd);
    }

    return hWnd;
}

using CreateWindowInBandEx_t = HWND(WINAPI*)(DWORD, LPCWSTR, LPCWSTR, DWORD, int, int, int, int, HWND, HMENU, HINSTANCE, PVOID, DWORD, DWORD);
static CreateWindowInBandEx_t CreateWindowInBandEx_Original;

static HWND WINAPI CreateWindowInBandEx_Hook(DWORD dwExStyle, LPCWSTR lpClassName, LPCWSTR lpWindowName, DWORD dwStyle,
                                             int X, int Y, int nWidth, int nHeight, HWND hWndParent, HMENU hMenu,
                                             HINSTANCE hInstance, PVOID lpParam, DWORD dwBand, DWORD dwTypeFlags) {
    HWND hWnd = CreateWindowInBandEx_Original(dwExStyle, lpClassName, lpWindowName, dwStyle,
                                             X, Y, nWidth, nHeight, hWndParent, hMenu, hInstance, lpParam, dwBand, dwTypeFlags);
    if (!hWnd) return hWnd;

    if (lpClassName && ((ULONG_PTR)lpClassName & ~(ULONG_PTR)0xffff) != 0 &&
        _wcsicmp(lpClassName, L"Windows.UI.Core.CoreWindow") == 0) {
        InitWithRetry(hWnd);
    }

    return hWnd;
}

// Helper to run a lambda on the target window's thread
using ThreadCallProc_t = void(WINAPI*)(PVOID);

static bool CallOnWindowThread(HWND hWnd, ThreadCallProc_t proc, PVOID param) {
    static const UINT msg = RegisterWindowMessage(THREAD_CALL_MSG);
    struct CallParam { ThreadCallProc_t proc; PVOID param; };

    DWORD threadId = GetWindowThreadProcessId(hWnd, nullptr);
    if (threadId == 0) return false;

    if (threadId == GetCurrentThreadId()) {
        proc(param);
        return true;
    }

    HHOOK hook = SetWindowsHookEx(
        WH_CALLWNDPROC,
        [](int nCode, WPARAM wParam, LPARAM lParam) -> LRESULT {
            if (nCode == HC_ACTION) {
                const CWPSTRUCT* cwp = (const CWPSTRUCT*)lParam;
                if (cwp->message == RegisterWindowMessage(THREAD_CALL_MSG)) {
                    CallParam* p = (CallParam*)cwp->lParam;
                    p->proc(p->param);
                }
            }
            return CallNextHookEx(nullptr, nCode, wParam, lParam);
        },
        nullptr, threadId);

    if (!hook) return false;

    CallParam p = { proc, param };
    SendMessage(hWnd, msg, 0, (LPARAM)&p);
    UnhookWindowsHookEx(hook);
    return true;
}

static HWND FindCoreWindow() {
    struct EnumParam { HWND* result; };
    HWND hWnd = nullptr;
    EnumParam param = { &hWnd };

    EnumWindows([](HWND w, LPARAM lParam) -> BOOL {
        EnumParam& p = *(EnumParam*)lParam;

        DWORD pid = 0;
        if (!GetWindowThreadProcessId(w, &pid) || pid != GetCurrentProcessId())
            return TRUE;

        WCHAR cls[64]{};
        if (GetClassName(w, cls, 64) == 0)
            return TRUE;

        if (_wcsicmp(cls, L"Windows.UI.Core.CoreWindow") == 0) {
            *p.result = w;
            return FALSE;
        }
        return TRUE;
    }, (LPARAM)&param);

    return hWnd;
}

// ============================================================================
// Mod Entry Points
// ============================================================================

BOOL Wh_ModInit() {
    if (IsExplorerProcess()) {
        StartProxyThread();
        return TRUE;
    }

    HMODULE user32 = LoadLibraryEx(L"user32.dll", nullptr, LOAD_LIBRARY_SEARCH_SYSTEM32);
    if (!user32) {
        Wh_Log(L"Inicio: no se pudo cargar user32.dll");
        return TRUE;
    }

    void* pCreateWindowInBand = (void*)GetProcAddress(user32, "CreateWindowInBand");
    if (pCreateWindowInBand) {
        Wh_SetFunctionHook(pCreateWindowInBand, (void*)CreateWindowInBand_Hook, (void**)&CreateWindowInBand_Original);
    } else {
        Wh_Log(L"Inicio: no se encontró CreateWindowInBand");
    }

    void* pCreateWindowInBandEx = (void*)GetProcAddress(user32, "CreateWindowInBandEx");
    if (pCreateWindowInBandEx) {
        Wh_SetFunctionHook(pCreateWindowInBandEx, (void*)CreateWindowInBandEx_Hook, (void**)&CreateWindowInBandEx_Original);
    } else {
        Wh_Log(L"Inicio: no se encontró CreateWindowInBandEx");
    }

    return TRUE;
}

void Wh_ModAfterInit() {
    if (IsExplorerProcess()) return;

    HWND hCoreWnd = FindCoreWindow();
    if (!hCoreWnd) {
        // Start Menu process started but no window yet. Hook will catch it.
        return;
    }

    CallOnWindowThread(hCoreWnd, [](PVOID hwnd) {
        InitWithRetry((HWND)hwnd);
    }, hCoreWnd);
}

void Wh_ModUninit() {
    g_unloading = true;

    if (g_proxyWindow) {
        PostMessage(g_proxyWindow, WM_CLOSE, 0, 0);
    }

    if (g_proxyThread) {
        WaitForSingleObject(g_proxyThread, 5000); 
        CloseHandle(g_proxyThread);
        g_proxyThread = NULL;
    }
    g_proxyWindow = NULL;

    if (!IsExplorerProcess()) {
        HWND hCoreWnd = FindCoreWindow();
        if (hCoreWnd) {
            CallOnWindowThread(hCoreWnd, [](PVOID) {
                StopVisibilityMonitoring();
            }, nullptr);
        }
    }
}

void Wh_ModSettingsChanged() {
    if (IsExplorerProcess()) return;

    g_forceRebuild = true;
    g_buttonsInjected = false;
    g_buttonContainer = nullptr;

    HWND hCoreWnd = FindCoreWindow();
    if (!hCoreWnd) return;

    CallOnWindowThread(hCoreWnd, [](PVOID) {
        LoadSettings();
        BuildButtons();
        TryInjectButtons();
    }, nullptr);
}

// ==WindhawkMod==
// @id              aether-margen-escritorio
// @name            Aether - Margen inferior del escritorio
// @description     Evita que la barra de tareas tape la última fila de íconos del escritorio cuando la barra está en auto-ocultar
// @version         1.0.0
// @author          Aether OS
// @include         explorer.exe
// @architecture    x86-64
// ==/WindhawkMod==

// Parte de Aether OS. Código publicado bajo la licencia GNU GPL v3.0.

// ==WindhawkModReadme==
/*
# Aether - Margen inferior del escritorio

Cuando la barra de tareas está en **auto-ocultar** (por ejemplo, con el mod
"Ocultar barra de tareas al maximizar"), Windows le da al escritorio toda la
pantalla y acomoda los íconos hasta el borde de abajo. Al aparecer la barra,
queda encima de la última fila y no se ven sus nombres.

Este mod reserva una franja abajo, del alto de la barra de tareas, donde el
escritorio **no pone íconos**. Las ventanas no cambian: al maximizar siguen
usando toda la pantalla.

**Funciona mejor con "Organizar iconos automáticamente" activado** (clic
derecho en el escritorio → Ver). Si lo tienes apagado, mueve a mano los íconos
que estén en la franja de abajo una sola vez.

Al desactivar el mod, el escritorio vuelve a como estaba.
*/
// ==/WindhawkModReadme==

// ==WindhawkModSettings==
/*
- extraMargin: 8
  $name: Margen extra (px)
  $description: >-
    Espacio adicional por encima de la barra de tareas. Súbelo si con la barra
    tipo dock todavía se tapa un poco el texto de los íconos.
- manualHeight: 0
  $name: Alto manual de la barra (px)
  $description: >-
    0 = detectar automáticamente el alto de la barra de tareas. Escribe un
    número solo si la detección automática no queda bien.
*/
// ==/WindhawkModSettings==

#include <commctrl.h>

#include <atomic>

struct {
    int extraMargin;
    int manualHeight;
} g_settings;

using ListViewWndProc_t = LRESULT(CALLBACK*)(HWND, UINT, WPARAM, LPARAM);
ListViewWndProc_t ListViewWndProc_Original;

constexpr int kMaxWorkAreas = LV_MAX_WORKAREAS;

std::atomic<HWND> g_listView{nullptr};
std::atomic<bool> g_hooked{false};
std::atomic<bool> g_disabled{false};
HANDLE g_thread = nullptr;
HANDLE g_stopEvent = nullptr;

// Las áreas de trabajo que Explorer quería, sin nuestro ajuste. Se usan para
// dejar todo como estaba al desactivar el mod.
CRITICAL_SECTION g_origLock;
RECT g_origRects[kMaxWorkAreas];
int g_origCount = 0;
bool g_haveOrig = false;

bool IsClass(HWND hWnd, LPCWSTR className) {
    WCHAR buffer[64];
    if (!hWnd || !GetClassNameW(hWnd, buffer, ARRAYSIZE(buffer))) {
        return false;
    }
    return _wcsicmp(buffer, className) == 0;
}

bool IsDesktopListView(HWND hWnd) {
    if (hWnd == g_listView.load()) {
        return true;
    }
    HWND defView = GetParent(hWnd);
    if (!IsClass(defView, L"SHELLDLL_DefView")) {
        return false;
    }
    HWND host = GetParent(defView);
    return IsClass(host, L"Progman") || IsClass(host, L"WorkerW");
}

HWND FindDesktopListView() {
    HWND defView = nullptr;
    if (HWND progman = FindWindowW(L"Progman", nullptr)) {
        defView = FindWindowExW(progman, nullptr, L"SHELLDLL_DefView", nullptr);
    }
    if (!defView) {
        HWND worker = nullptr;
        while ((worker = FindWindowExW(nullptr, worker, L"WorkerW", nullptr))) {
            defView = FindWindowExW(worker, nullptr, L"SHELLDLL_DefView", nullptr);
            if (defView) {
                break;
            }
        }
    }
    if (!defView) {
        return nullptr;
    }
    HWND listView = FindWindowExW(defView, nullptr, L"SysListView32", nullptr);
    if (!listView) {
        return nullptr;
    }
    DWORD pid = 0;
    GetWindowThreadProcessId(listView, &pid);
    return pid == GetCurrentProcessId() ? listView : nullptr;
}

// Alto de la barra de tareas que está abajo en el monitor indicado (0 si no hay).
int GetBottomTaskbarHeight(HMONITOR monitor, const RECT& monitorRect) {
    if (g_settings.manualHeight > 0) {
        return g_settings.manualHeight;
    }

    HWND taskbars[16];
    int count = 0;
    if (HWND primary = FindWindowW(L"Shell_TrayWnd", nullptr)) {
        taskbars[count++] = primary;
    }
    HWND secondary = nullptr;
    while (count < ARRAYSIZE(taskbars) &&
           (secondary = FindWindowExW(nullptr, secondary,
                                      L"Shell_SecondaryTrayWnd", nullptr))) {
        taskbars[count++] = secondary;
    }

    for (int i = 0; i < count; i++) {
        if (MonitorFromWindow(taskbars[i], MONITOR_DEFAULTTONEAREST) !=
            monitor) {
            continue;
        }
        RECT rc;
        if (!GetWindowRect(taskbars[i], &rc)) {
            continue;
        }
        int width = rc.right - rc.left;
        int height = rc.bottom - rc.top;
        int monitorCenterY = (monitorRect.top + monitorRect.bottom) / 2;
        bool horizontal = width >= height;
        bool atBottom = (rc.top + rc.bottom) / 2 > monitorCenterY;
        // Con auto-ocultar, la ventana conserva su alto aunque esté escondida.
        if (horizontal && atBottom && height > 0 && height < 400) {
            return height;
        }
    }
    return 0;
}

void AdjustRects(HWND listView, RECT* rects, int count) {
    for (int i = 0; i < count; i++) {
        RECT r = rects[i];
        MapWindowPoints(listView, HWND_DESKTOP, reinterpret_cast<POINT*>(&r), 2);

        HMONITOR monitor = MonitorFromRect(&r, MONITOR_DEFAULTTONEAREST);
        MONITORINFO mi{sizeof(mi)};
        if (!GetMonitorInfoW(monitor, &mi)) {
            continue;
        }

        int taskbarHeight = GetBottomTaskbarHeight(monitor, mi.rcMonitor);
        if (taskbarHeight <= 0) {
            continue;
        }

        LONG limit = mi.rcMonitor.bottom - taskbarHeight - g_settings.extraMargin;
        // Solo recorta si hace falta, y nunca deja un área ridículamente chica.
        if (r.bottom > limit && limit - r.top > 200) {
            r.bottom = limit;
            MapWindowPoints(HWND_DESKTOP, listView, reinterpret_cast<POINT*>(&r),
                            2);
            rects[i].bottom = r.bottom;
        }
    }
}

LRESULT CALLBACK ListViewWndProc_Hook(HWND hWnd,
                                      UINT msg,
                                      WPARAM wParam,
                                      LPARAM lParam) {
    if (msg != LVM_SETWORKAREAS || !IsDesktopListView(hWnd)) {
        return ListViewWndProc_Original(hWnd, msg, wParam, lParam);
    }

    int count = static_cast<int>(wParam);
    const RECT* source = reinterpret_cast<const RECT*>(lParam);
    if (count < 0 || !source) {
        count = 0;
    }
    if (count > kMaxWorkAreas) {
        count = kMaxWorkAreas;
    }

    EnterCriticalSection(&g_origLock);
    g_origCount = count;
    if (count > 0) {
        memcpy(g_origRects, source, count * sizeof(RECT));
    }
    g_haveOrig = true;
    LeaveCriticalSection(&g_origLock);

    if (g_disabled) {
        return ListViewWndProc_Original(hWnd, msg, wParam, lParam);
    }

    RECT rects[kMaxWorkAreas];
    if (count > 0) {
        memcpy(rects, source, count * sizeof(RECT));
    } else {
        // Sin áreas definidas, el escritorio usa toda la ventana.
        GetClientRect(hWnd, &rects[0]);
        count = 1;
    }

    AdjustRects(hWnd, rects, count);

    Wh_Log(L"Áreas de trabajo ajustadas: %d", count);
    return ListViewWndProc_Original(hWnd, msg, count,
                                    reinterpret_cast<LPARAM>(rects));
}

void ArrangeIfAuto(HWND listView) {
    if (GetWindowLongPtrW(listView, GWL_STYLE) & LVS_AUTOARRANGE) {
        SendMessageW(listView, LVM_ARRANGE, LVA_DEFAULT, 0);
    }
}

// Vuelve a mandar las áreas de Explorer para que pasen por el ajuste.
void Reapply(HWND listView) {
    RECT rects[kMaxWorkAreas];
    int count = 0;

    EnterCriticalSection(&g_origLock);
    bool haveOrig = g_haveOrig;
    if (haveOrig) {
        count = g_origCount;
        memcpy(rects, g_origRects, sizeof(rects));
    }
    LeaveCriticalSection(&g_origLock);

    if (!haveOrig) {
        UINT current = 0;
        SendMessageW(listView, LVM_GETNUMBEROFWORKAREAS, 0,
                     reinterpret_cast<LPARAM>(&current));
        count = static_cast<int>(current > kMaxWorkAreas ? kMaxWorkAreas
                                                         : current);
        if (count > 0) {
            SendMessageW(listView, LVM_GETWORKAREAS, count,
                         reinterpret_cast<LPARAM>(rects));
        }
    }

    SendMessageW(listView, LVM_SETWORKAREAS, count,
                 count > 0 ? reinterpret_cast<LPARAM>(rects) : 0);
    ArrangeIfAuto(listView);
}

bool HookListView(HWND listView, bool applyNow) {
    if (g_hooked) {
        return true;
    }
    auto wndProc = reinterpret_cast<ListViewWndProc_t>(
        GetClassLongPtrW(listView, GCLP_WNDPROC));
    if (!wndProc) {
        Wh_Log(L"No se encontró el procedimiento de la lista del escritorio");
        return false;
    }
    if (!Wh_SetFunctionHook(reinterpret_cast<void*>(wndProc),
                            reinterpret_cast<void*>(ListViewWndProc_Hook),
                            reinterpret_cast<void**>(&ListViewWndProc_Original))) {
        Wh_Log(L"No se pudo instalar el hook");
        return false;
    }
    if (applyNow) {
        Wh_ApplyHookOperations();
    }
    g_hooked = true;
    return true;
}

// Firma simple del estado de las barras de tareas para detectar cambios de alto.
LONG TaskbarSignature() {
    LONG signature = g_settings.extraMargin * 7919 + g_settings.manualHeight;
    if (HWND tray = FindWindowW(L"Shell_TrayWnd", nullptr)) {
        RECT rc;
        if (GetWindowRect(tray, &rc)) {
            signature = signature * 31 + (rc.bottom - rc.top);
            signature = signature * 31 + (rc.right - rc.left);
        }
    }
    return signature;
}

DWORD WINAPI WatcherThread(LPVOID) {
    LONG lastSignature = 0;
    for (;;) {
        HWND listView = FindDesktopListView();
        if (listView) {
            bool isNew = listView != g_listView.load();
            if (isNew) {
                EnterCriticalSection(&g_origLock);
                g_haveOrig = false;
                LeaveCriticalSection(&g_origLock);
                g_listView = listView;
            }
            if (HookListView(listView, true)) {
                LONG signature = TaskbarSignature();
                if (isNew || signature != lastSignature) {
                    lastSignature = signature;
                    Reapply(listView);
                }
            }
        }
        if (WaitForSingleObject(g_stopEvent, 2000) == WAIT_OBJECT_0) {
            break;
        }
    }
    return 0;
}

void LoadSettings() {
    g_settings.extraMargin = Wh_GetIntSetting(L"extraMargin");
    g_settings.manualHeight = Wh_GetIntSetting(L"manualHeight");
    if (g_settings.extraMargin < 0) {
        g_settings.extraMargin = 0;
    }
    if (g_settings.extraMargin > 300) {
        g_settings.extraMargin = 300;
    }
    if (g_settings.manualHeight < 0) {
        g_settings.manualHeight = 0;
    }
}

BOOL Wh_ModInit() {
    Wh_Log(L">");
    InitializeCriticalSection(&g_origLock);
    LoadSettings();

    if (HWND listView = FindDesktopListView()) {
        g_listView = listView;
        HookListView(listView, false);
    }
    return TRUE;
}

void Wh_ModAfterInit() {
    Wh_Log(L">");
    g_stopEvent = CreateEventW(nullptr, TRUE, FALSE, nullptr);
    g_thread = CreateThread(nullptr, 0, WatcherThread, nullptr, 0, nullptr);
}

void Wh_ModBeforeUninit() {
    Wh_Log(L">");
    if (g_thread) {
        SetEvent(g_stopEvent);
        WaitForSingleObject(g_thread, INFINITE);
        CloseHandle(g_thread);
        g_thread = nullptr;
    }
    if (g_stopEvent) {
        CloseHandle(g_stopEvent);
        g_stopEvent = nullptr;
    }

    // Deja el escritorio exactamente como lo quería Explorer.
    g_disabled = true;
    HWND listView = g_listView.load();
    if (listView && IsWindow(listView) && g_hooked) {
        RECT rects[kMaxWorkAreas];
        int count = 0;
        EnterCriticalSection(&g_origLock);
        bool haveOrig = g_haveOrig;
        count = g_origCount;
        memcpy(rects, g_origRects, sizeof(rects));
        LeaveCriticalSection(&g_origLock);
        if (haveOrig) {
            SendMessageW(listView, LVM_SETWORKAREAS, count,
                         count > 0 ? reinterpret_cast<LPARAM>(rects) : 0);
            ArrangeIfAuto(listView);
        }
    }
}

void Wh_ModUninit() {
    Wh_Log(L">");
    DeleteCriticalSection(&g_origLock);
}

void Wh_ModSettingsChanged() {
    Wh_Log(L">");
    LoadSettings();
    HWND listView = g_listView.load();
    if (listView && IsWindow(listView) && g_hooked) {
        Reapply(listView);
    }
}
